//! Bond order definitions and lookup utilities
//!
//! Provides bond order inference for standard residues.
//! Default bond order is 1 (Single).
//!
//! Bond orders:
//! 1 = Single
//! 2 = Double
//! 3 = Triple
//! 4 = Aromatic (PyMOL/ChemFiles convention often uses 4, or treated as 1.5)

/// Get bond order for a bond between two atoms in a residue.
///
/// # Arguments
/// * `res_name` - Residue name (e.g. "ALA")
/// * `atom1` - Atom 1 name
/// * `atom2` - Atom 2 name
///
/// # Returns
/// Bond order (1, 2, 3, or 4). Default is 1.
pub fn get_bond_order(res_name: &str, atom1: &str, atom2: &str) -> u8 {
    // Normalize names (trim whitespace if needed, though they usually come clean)
    // Order doesn't matter, check both ways by sorting
    let (a, b) = if atom1 < atom2 {
        (atom1, atom2)
    } else {
        (atom2, atom1)
    };

    // 1. Backbone Carbonyl: (C, O) is always Double (2) in standard amino acids
    if a == "C" && b == "O" {
        return 2;
    }

    // 2. Sidechain Rules by Residue
    match res_name {
        "ASP" => {
            if a == "CG" && (b == "OD1" || b == "OD2") {
                return 2;
            }
        }
        "GLU" => {
            if a == "CD" && (b == "OE1" || b == "OE2") {
                return 2;
            }
        }
        "ASN" => {
            // CG-OD1 (Double), CG-ND2 (Single)
            if a == "CG" && b == "OD1" {
                return 2;
            }
        }
        "GLN" => {
            // CD-OE1 (Double), CD-NE2 (Single)
            if a == "CD" && b == "OE1" {
                return 2;
            }
        }
        "ARG" => {
            return 4; // Treat as aromatic/resonant within the group
        }
        "HIS" | "HIE" | "HID" | "HIP" => {
            // Imidazole ring: Aromatic
            if is_ring_atom_his(a) && is_ring_atom_his(b) {
                return 4;
            }
        }
        "PHE" | "TYR" => {
            // Phenyl ring
            if is_ring_atom_phe_tyr(a) && is_ring_atom_phe_tyr(b) {
                return 4;
            }
        }
        "TRP" => {
            // Indole ring
            if is_ring_atom_trp(a) && is_ring_atom_trp(b) {
                return 4;
            }
        }
        _ => {}
    }

    // Default Single
    1
}

fn is_ring_atom_his(name: &str) -> bool {
    matches!(name, "CG" | "ND1" | "CE1" | "NE2" | "CD2")
}

fn is_ring_atom_phe_tyr(name: &str) -> bool {
    matches!(name, "CG" | "CD1" | "CD2" | "CE1" | "CE2" | "CZ")
}

fn is_ring_atom_trp(name: &str) -> bool {
    matches!(
        name,
        "CG" | "CD1" | "CD2" | "NE1" | "CE2" | "CE3" | "CZ2" | "CZ3" | "CH2"
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_backbone_carbonyl() {
        assert_eq!(get_bond_order("ALA", "C", "O"), 2);
        assert_eq!(get_bond_order("ALA", "O", "C"), 2);
    }

    #[test]
    fn test_asp_carboxylate() {
        assert_eq!(get_bond_order("ASP", "CG", "OD1"), 2);
        assert_eq!(get_bond_order("ASP", "CG", "OD2"), 2);
    }

    #[test]
    fn test_glu_carboxylate() {
        assert_eq!(get_bond_order("GLU", "CD", "OE1"), 2);
        assert_eq!(get_bond_order("GLU", "CD", "OE2"), 2);
    }

    #[test]
    fn test_aromatic_rings() {
        // HIS ring
        assert_eq!(get_bond_order("HIS", "CG", "ND1"), 4);
        // PHE ring
        assert_eq!(get_bond_order("PHE", "CG", "CD1"), 4);
        // TRP ring
        assert_eq!(get_bond_order("TRP", "CG", "CD1"), 4);
    }

    #[test]
    fn test_default_single_bond() {
        assert_eq!(get_bond_order("ALA", "CA", "CB"), 1);
        assert_eq!(get_bond_order("GLY", "N", "CA"), 1);
    }
}

//! EspalomaCharge: Machine Learning-Enabled Ultrafast Partial Charge Assignment
//!
//! Port of EspalomaCharge to Rust with embedded weights.
//! Provides AM1-BCC quality partial charges orders of magnitude faster than traditional methods.
//!
//! ## Citation
//! Wang Y, Pulido I, Takaba K, Kaminow B, Scheen J, Wang L, Chodera JD.
//! "EspalomaCharge: Machine Learning-Enabled Ultrafast Partial Charge Assignment"
//! J. Phys. Chem. A 2024, 128, 20, 4160-4167. DOI: 10.1021/acs.jpca.4c01287
//! arXiv: https://arxiv.org/abs/2302.06758
//! GitHub: https://github.com/choderalab/espaloma_charge
//!
//! ## Architecture
//! - Espaloma v0.0.8 with SAGE graph neural network
//! - 4-layer message passing
//! - 128 hidden units per layer
//! - 116 feature dimensions

use bytemuck;
use nalgebra::{DMatrix, DVector};

/// Constants for the Espaloma v0.0.8 architecture
pub const FEATURE_UNITS: usize = 116;
pub const INPUT_UNITS: usize = 128;
pub const SAGE_HIDDEN: usize = 128;
pub const N_SAGE_LAYERS: usize = 4;

/// Embedded weights binary
#[repr(C, align(4))]
struct AlignedWeights<const N: usize>([u8; N]);

static WEIGHTS_BLOB: AlignedWeights<587284> =
    AlignedWeights(*include_bytes!("espaloma_v0_0_8.bin"));

pub static EMBEDDED_WEIGHTS: &[u8] = &WEIGHTS_BLOB.0;

/// Espaloma weight bundle
#[derive(Debug)]
pub struct EspalomaWeights {
    pub w_f_in: DMatrix<f32>,
    pub b_f_in: DVector<f32>,
    pub sages: Vec<SAGEWeights>,
    pub w_readout: DMatrix<f32>,
    pub b_readout: DVector<f32>,
}

#[derive(Debug)]
pub struct SAGEWeights {
    pub w_self: DMatrix<f32>,
    pub b_self: DVector<f32>,
    pub w_neigh: DMatrix<f32>,
}

impl EspalomaWeights {
    /// Load weights from a raw binary blob (generated by export_weights.py)
    pub fn from_bytes(bytes: &[u8]) -> Result<Self, String> {
        if bytes.len() < 12 {
            return Err("Weight bundle too short".to_string());
        }

        // Simple manual check for safety (expect magic EXPA + version 1)
        if &bytes[0..4] != b"EXPA" {
            return Err("Invalid weight bundle magic".to_string());
        }

        if u32::from_le_bytes(bytes[4..8].try_into().unwrap()) != 1 {
            return Err("Unsupported weight bundle version".to_string());
        }

        let num_layers = u32::from_le_bytes(bytes[8..12].try_into().unwrap()) as usize;
        if num_layers != N_SAGE_LAYERS {
            return Err(format!("Expected {} layers, found {}", N_SAGE_LAYERS, num_layers));
        }

        let data_len = bytes.len() - 12;
        let expected_len = (INPUT_UNITS * FEATURE_UNITS + INPUT_UNITS) * 4
            + N_SAGE_LAYERS * (SAGE_HIDDEN * SAGE_HIDDEN * 2 + SAGE_HIDDEN) * 4
            + (2 * SAGE_HIDDEN + 2) * 4;

        if data_len < expected_len {
            return Err(format!("Data length mismatch: expected {}, got {}", expected_len, data_len));
        }

        let data: &[f32] = bytemuck::cast_slice(&bytes[12..]);
        let mut pos = 0;

        // Projection
        let w_f_in = DM::from_row_slice(
            INPUT_UNITS,
            FEATURE_UNITS,
            &data[pos..pos + INPUT_UNITS * FEATURE_UNITS],
        );
        pos += INPUT_UNITS * FEATURE_UNITS;
        let b_f_in = DV::from_column_slice(&data[pos..pos + INPUT_UNITS]);
        pos += INPUT_UNITS;

        // SAGE Layers
        let mut sages = Vec::with_capacity(N_SAGE_LAYERS);
        for _ in 0..N_SAGE_LAYERS {
            let w_self = DM::from_row_slice(
                SAGE_HIDDEN,
                SAGE_HIDDEN,
                &data[pos..pos + SAGE_HIDDEN * SAGE_HIDDEN],
            );
            pos += SAGE_HIDDEN * SAGE_HIDDEN;
            let b_self = DV::from_column_slice(&data[pos..pos + SAGE_HIDDEN]);
            pos += SAGE_HIDDEN;
            let w_neigh = DM::from_row_slice(
                SAGE_HIDDEN,
                SAGE_HIDDEN,
                &data[pos..pos + SAGE_HIDDEN * SAGE_HIDDEN],
            );
            pos += SAGE_HIDDEN * SAGE_HIDDEN;
            sages.push(SAGEWeights {
                w_self,
                b_self,
                w_neigh,
            });
        }

        // Readout (2 output units: electronegativity and hardness)
        let w_readout = DM::from_row_slice(2, SAGE_HIDDEN, &data[pos..pos + 2 * SAGE_HIDDEN]);
        pos += 2 * SAGE_HIDDEN;
        let b_readout = DV::from_column_slice(&data[pos..pos + 2]);

        Ok(Self {
            w_f_in,
            b_f_in,
            sages,
            w_readout,
            b_readout,
        })
    }
}

type DM = DMatrix<f32>;
type DV = DVector<f32>;

/// Main inference entry point
pub fn infer_charges(
    weights: &EspalomaWeights,
    x: &DM, // (n_atoms, FEATURE_UNITS)
    senders: &[u32],
    receivers: &[u32],
    segment_ids: &[u32],
    num_graphs: usize,
    total_charges: &[f32], // per graph
) -> Vec<f32> {
    let n_atoms = x.nrows();

    // 1. Initial projection + Tanh
    // (n_atoms, 116) * (128, 116)^T + (128,)
    let mut h = (x * weights.w_f_in.transpose()).row_add_vec(&weights.b_f_in);
    h.apply(|v| *v = v.tanh());

    // 2. SAGE Layers
    for sage in &weights.sages {
        // Self loop contribution
        let h_self = (&h * sage.w_self.transpose()).row_add_vec(&sage.b_self);

        // Neighborhood aggregation (Mean)
        // DGL/Expaloma logic: agg = sum_m / deg
        let mut agg = DM::zeros(n_atoms, SAGE_HIDDEN);
        let mut deg = vec![0.0f32; n_atoms];

        for (&s, &r) in senders.iter().zip(receivers.iter()) {
            let s = s as usize;
            let r = r as usize;
            // Neighborhood transform after aggregation in DGL SAGEConv source (default)
            // msg = x[senders]
            // sum_m = scatter_add(msg, receivers)
            // agg = sum_m / deg
            // neigh_mean = agg @ w_neigh.T

            // Optimization: we can sum features then transform, or transform then sum.
            // Expaloma layers.py says: if in_feats > out_feats, transform before, else after.
            // Here in_feats(128) == out_feats(128), so "else" (after) applies.

            // Sum neighbor features into receiver
            let src_row = h.row(s);
            let mut dst_row = agg.row_mut(r);
            dst_row += src_row;
            deg[r] += 1.0;
        }

        // Normalize by degree
        for (i, deg_val) in deg.iter().enumerate().take(n_atoms) {
            if *deg_val > 0.0 {
                let mut row = agg.row_mut(i);
                row /= *deg_val;
            }
        }

        let h_neigh = agg * sage.w_neigh.transpose();

        h = h_self + h_neigh;
        h.apply(|v| *v = v.max(0.0)); // ReLU
    }

    // 3. Readout (E, S)
    let es = (h * weights.w_readout.transpose()).row_add_vec(&weights.b_readout);
    let e = es.column(0);
    let s = es.column(1);

    // 4. QEq (Charge Equilibrium)
    // q = -e * s_inv + s_inv * (tc_n + sum_e_s_inv_n) / sum_s_inv_n
    let s_inv: Vec<f32> = s.iter().map(|&val| 1.0 / val).collect();
    let e_s_inv: Vec<f32> = e
        .iter()
        .zip(s_inv.iter())
        .map(|(&ei, &si)| ei * si)
        .collect();

    let mut sum_s_inv = vec![0.0f32; num_graphs];
    let mut sum_e_s_inv = vec![0.0f32; num_graphs];

    for i in 0..n_atoms {
        let sid = segment_ids[i] as usize;
        sum_s_inv[sid] += s_inv[i];
        sum_e_s_inv[sid] += e_s_inv[i];
    }

    let mut charges = Vec::with_capacity(n_atoms);
    for i in 0..n_atoms {
        let sid = segment_ids[i] as usize;
        let si_inv = s_inv[i];
        let qi = -e[i] * si_inv + si_inv * (total_charges[sid] + sum_e_s_inv[sid]) / sum_s_inv[sid];
        charges.push(qi);
    }

    charges
}

/// Helper trait to add a vector to every row of a matrix
trait RowAddInplace {
    fn row_add_vec(&self, vec: &DVector<f32>) -> DMatrix<f32>;
}

impl RowAddInplace for DMatrix<f32> {
    fn row_add_vec(&self, vec: &DVector<f32>) -> DMatrix<f32> {
        let mut out = self.clone();
        for mut row in out.row_iter_mut() {
            row += vec.transpose();
        }
        out
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_weight_bundle_load_fail() {
        let bad_data = b"FAIL000000000000000000000000";
        let result = EspalomaWeights::from_bytes(bad_data);
        assert!(result.is_err());
    }

    #[test]
    fn test_weight_bundle_load_insufficient_data() {
        // Correct magic and version, but wrong size
        let mut data = vec![0u8; 12];
        data[0..4].copy_from_slice(b"EXPA");
        data[4..8].copy_from_slice(&1u32.to_le_bytes());
        data[8..12].copy_from_slice(&4u32.to_le_bytes());

        let result = EspalomaWeights::from_bytes(&data);
        assert!(result.is_err());
        assert!(result.unwrap_err().contains("Data length mismatch"));
    }

    #[test]
    fn test_constants() {
        assert_eq!(FEATURE_UNITS, 116);
        assert_eq!(SAGE_HIDDEN, 128);
        assert_eq!(N_SAGE_LAYERS, 4);
    }
}

//! Atomic mass assignment utilities
//!
//! Provides functions to assign atomic masses based on element type.
//! Used for MD simulations.

/// Default mass for unknown elements
pub const DEFAULT_MASS: f32 = 12.0;

/// Get atomic mass for an element symbol
pub fn get_mass(element: &str) -> f32 {
    match element {
        "H" => 1.008,
        "C" => 12.011,
        "N" => 14.007,
        "O" => 15.999,
        "S" => 32.06,
        "P" => 30.97,
        "F" => 18.998,
        "Cl" => 35.45,
        "Br" => 79.904,
        "I" => 126.90,
        "Na" => 22.990,
        "K" => 39.098,
        "Ca" => 40.078,
        "Mg" => 24.305,
        "Zn" => 65.38,
        "Fe" => 55.845,
        "Cu" => 63.546,
        "Mn" => 54.938,
        "Se" => 78.971,
        _ => DEFAULT_MASS,
    }
}

/// Assign atomic masses based on atom names
///
/// Infers the element from the first character(s) of the atom name
/// and looks up the mass from the standard atomic masses table.
///
/// # Arguments
/// * `atom_names` - List of atom names (e.g., ["N", "CA", "C", "O", "H"])
///
/// # Returns
/// * List of masses in amu
pub fn assign_masses(atom_names: &[String]) -> Vec<f32> {
    atom_names
        .iter()
        .map(|name| {
            let element = infer_element(name);
            get_mass(element)
        })
        .collect()
}

/// Infer element from atom name
///
/// Follows PDB conventions where element is typically the first 1-2 characters
fn infer_element(atom_name: &str) -> &str {
    let name = atom_name.trim();
    if name.is_empty() {
        return "C";
    }

    // Check for common two-character elements first
    if name.len() >= 2 {
        let two_char = &name[..2];
        match two_char {
            "Cl" | "CL" => return "Cl",
            "Br" | "BR" => return "Br",
            "Na" | "NA" => return "Na",
            "Mg" | "MG" => return "Mg",
            "Zn" | "ZN" => return "Zn",
            "Fe" | "FE" => return "Fe",
            "Cu" | "CU" => return "Cu",
            "Mn" | "MN" => return "Mn",
            "Se" | "SE" => return "Se",
            _ => {}
        }
    }

    // Default: use first character
    let first = name.chars().next().unwrap();
    match first {
        'H' | 'h' => "H",
        'C' | 'c' => "C",
        'N' | 'n' => "N",
        'O' | 'o' => "O",
        'S' | 's' => "S",
        'P' | 'p' => "P",
        'F' | 'f' => "F",
        'I' | 'i' => "I",
        'K' | 'k' => "K",
        _ => "C", // Default to carbon
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_assign_masses() {
        let names = vec![
            "N".to_string(),
            "CA".to_string(),
            "C".to_string(),
            "O".to_string(),
            "H".to_string(),
        ];
        let masses = assign_masses(&names);

        assert!((masses[0] - 14.007).abs() < 0.001); // N
        assert!((masses[1] - 12.011).abs() < 0.001); // CA -> C
        assert!((masses[2] - 12.011).abs() < 0.001); // C
        assert!((masses[3] - 15.999).abs() < 0.001); // O
        assert!((masses[4] - 1.008).abs() < 0.001); // H
    }

    #[test]
    fn test_infer_element() {
        assert_eq!(infer_element("CA"), "C"); // Alpha carbon
        assert_eq!(infer_element("N"), "N");
        assert_eq!(infer_element("CL"), "Cl");
        assert_eq!(infer_element("Na"), "Na");
        assert_eq!(infer_element("FE"), "Fe");
    }
}

//! Chemistry module for protein structures

pub mod bonds;
pub mod inference;
pub mod masses;
pub mod residues;

pub use residues::*;
// Note: bonds and masses modules are available but not re-exported
// Use chem::bonds::* or chem::masses::* directly if needed

//! Chemistry constants for protein structures
//!
//! This module contains constants ported from proxide/chem/residues.py
//! for residue types, atom ordering, and residue-specific atom masks.
//!
//! Note: Some utilities are used internally and will be fully exposed later.

#![allow(dead_code)]

use std::collections::HashMap;

/// Standard 20 amino acids in alphabetical order (AlphaFold convention)
pub const RESTYPES: [&str; 20] = [
    "A", "R", "N", "D", "C", "Q", "E", "G", "H", "I", "L", "K", "M", "F", "P", "S", "T", "W", "Y",
    "V",
];

/// 1-letter to 3-letter code mapping
pub const RESTYPE_1TO3: [(&str, &str); 20] = [
    ("A", "ALA"),
    ("R", "ARG"),
    ("N", "ASN"),
    ("D", "ASP"),
    ("C", "CYS"),
    ("Q", "GLN"),
    ("E", "GLU"),
    ("G", "GLY"),
    ("H", "HIS"),
    ("I", "ILE"),
    ("L", "LEU"),
    ("K", "LYS"),
    ("M", "MET"),
    ("F", "PHE"),
    ("P", "PRO"),
    ("S", "SER"),
    ("T", "THR"),
    ("W", "TRP"),
    ("Y", "TYR"),
    ("V", "VAL"),
];

/// Atom37 ordering - standard atom types
pub const ATOM_TYPES: [&str; 37] = [
    "N", "CA", "C", "CB", "O", "CG", "CG1", "CG2", "OG", "OG1", "SG", "CD", "CD1", "CD2", "ND1",
    "ND2", "OD1", "OD2", "SD", "CE", "CE1", "CE2", "CE3", "NE", "NE1", "NE2", "OE1", "OE2", "CH2",
    "NH1", "NH2", "OH", "CZ", "CZ2", "CZ3", "NZ", "OXT",
];

/// Number of atom types in atom37 format
pub const ATOM_TYPE_NUM: usize = 37;

/// Number of standard residue types (20 amino acids)
pub const RESTYPE_NUM: usize = 20;

/// Index for unknown residue type
pub const UNK_RESTYPE_INDEX: usize = 20;

/// Build atom order mapping (atom name -> index)
pub fn build_atom_order() -> HashMap<String, usize> {
    ATOM_TYPES
        .iter()
        .enumerate()
        .map(|(i, name)| (name.to_string(), i))
        .collect()
}

/// Build 3-letter to index mapping
pub fn build_resname_to_idx() -> HashMap<String, usize> {
    let mut map = HashMap::new();
    for (i, (_, three)) in RESTYPE_1TO3.iter().enumerate() {
        map.insert(three.to_string(), i);
    }
    map.insert("UNK".to_string(), UNK_RESTYPE_INDEX);
    map
}

/// Build 1-letter to index mapping
pub fn build_restype_order() -> HashMap<String, usize> {
    RESTYPES
        .iter()
        .enumerate()
        .map(|(i, letter)| (letter.to_string(), i))
        .collect()
}

/// Atoms present in each residue type (excluding hydrogens)
/// Returns a 21x37 mask array where mask[restype][atom_type] = 1 if present
pub fn build_standard_atom_mask() -> Vec<Vec<u8>> {
    let atom_order = build_atom_order();
    let mut mask = vec![vec![0u8; ATOM_TYPE_NUM]; RESTYPE_NUM + 1];

    // Define atoms for each residue type
    let residue_atoms = get_residue_atoms();

    for (i, (_, three_letter)) in RESTYPE_1TO3.iter().enumerate() {
        if let Some(atoms) = residue_atoms.get(*three_letter) {
            for atom_name in atoms {
                if let Some(&atom_idx) = atom_order.get(*atom_name) {
                    mask[i][atom_idx] = 1;
                }
            }
        }
    }

    // Index 20 is for unknown residues - all zeros
    mask
}

/// Get atoms for each residue type
fn get_residue_atoms() -> HashMap<&'static str, Vec<&'static str>> {
    let mut map = HashMap::new();

    map.insert("ALA", vec!["C", "CA", "CB", "N", "O"]);
    map.insert(
        "ARG",
        vec![
            "C", "CA", "CB", "CG", "CD", "CZ", "N", "NE", "O", "NH1", "NH2",
        ],
    );
    map.insert("ASP", vec!["C", "CA", "CB", "CG", "N", "O", "OD1", "OD2"]);
    map.insert("ASN", vec!["C", "CA", "CB", "CG", "N", "ND2", "O", "OD1"]);
    map.insert("CYS", vec!["C", "CA", "CB", "N", "O", "SG"]);
    map.insert(
        "GLU",
        vec!["C", "CA", "CB", "CG", "CD", "N", "O", "OE1", "OE2"],
    );
    map.insert(
        "GLN",
        vec!["C", "CA", "CB", "CG", "CD", "N", "NE2", "O", "OE1"],
    );
    map.insert("GLY", vec!["C", "CA", "N", "O"]);
    map.insert(
        "HIS",
        vec!["C", "CA", "CB", "CG", "CD2", "CE1", "N", "ND1", "NE2", "O"],
    );
    map.insert("ILE", vec!["C", "CA", "CB", "CG1", "CG2", "CD1", "N", "O"]);
    map.insert("LEU", vec!["C", "CA", "CB", "CG", "CD1", "CD2", "N", "O"]);
    map.insert(
        "LYS",
        vec!["C", "CA", "CB", "CG", "CD", "CE", "N", "NZ", "O"],
    );
    map.insert("MET", vec!["C", "CA", "CB", "CG", "CE", "N", "O", "SD"]);
    map.insert(
        "PHE",
        vec![
            "C", "CA", "CB", "CG", "CD1", "CD2", "CE1", "CE2", "CZ", "N", "O",
        ],
    );
    map.insert("PRO", vec!["C", "CA", "CB", "CG", "CD", "N", "O"]);
