//! Molecular topology generation
//!
//! Generates bonds, angles, and dihedrals from atom coordinates and connectivity.
//! Used for MD simulation setup.

#![allow(dead_code)]

use std::collections::{HashMap, HashSet};

/// Bond between two atoms
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct Bond {
    pub i: usize,
    pub j: usize,
}

impl Bond {
    pub fn new(i: usize, j: usize) -> Self {
        // Canonical order
        if i < j {
            Self { i, j }
        } else {
            Self { i: j, j: i }
        }
    }
}

/// Angle between three atoms (i-j-k, with j as the central atom)
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct Angle {
    pub i: usize,
    pub j: usize, // Central atom
    pub k: usize,
}

impl Angle {
    pub fn new(i: usize, j: usize, k: usize) -> Self {
        // Canonical order: i < k
        if i < k {
            Self { i, j, k }
        } else {
            Self { i: k, j, k: i }
        }
    }
}

/// Dihedral/torsion between four atoms (i-j-k-l)
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct Dihedral {
    pub i: usize,
    pub j: usize,
    pub k: usize,
    pub l: usize,
    pub is_improper: bool,
}

impl Dihedral {
    pub fn new_proper(i: usize, j: usize, k: usize, l: usize) -> Self {
        // Canonical order: middle bond j-k should have j < k for proper torsions
        if j < k {
            Self {
                i,
                j,
                k,
                l,
                is_improper: false,
            }
        } else {
            Self {
                i: l,
                j: k,
                k: j,
                l: i,
                is_improper: false,
            }
        }
    }

    pub fn new_improper(central: usize, a: usize, b: usize, c: usize) -> Self {
        // Improper: central atom is j, others sorted
        let mut others = [a, b, c];
        others.sort();
        Self {
            i: others[0],
            j: central,
            k: others[1],
            l: others[2],
            is_improper: true,
        }
    }
}

/// Complete molecular topology
#[derive(Debug, Clone)]
pub struct Topology {
    pub bonds: Vec<Bond>,
    pub angles: Vec<Angle>,
    pub proper_dihedrals: Vec<Dihedral>,
    pub improper_dihedrals: Vec<Dihedral>,
    /// Maps atom index to list of bonded neighbors
    pub adjacency: HashMap<usize, Vec<usize>>,
}

impl Topology {
    /// Build topology from existing bonds and elements
    pub fn new(bonds: Vec<Bond>, elements: &[String]) -> Self {
        // Build adjacency list
        let mut adjacency: HashMap<usize, Vec<usize>> = HashMap::new();
        for bond in &bonds {
            adjacency.entry(bond.i).or_default().push(bond.j);
            adjacency.entry(bond.j).or_default().push(bond.i);
        }

        // Generate angles (i-j-k where i-j and j-k are bonds)
        let angles = Self::generate_angles(&adjacency);

        // Generate proper dihedrals (i-j-k-l where i-j, j-k, k-l are bonds)
        let proper_dihedrals = Self::generate_proper_dihedrals(&adjacency);

        // Generate improper dihedrals (for planar groups like sp2 carbons)
        let improper_dihedrals = Self::generate_improper_dihedrals(&adjacency, elements);

        Self {
            bonds,
            angles,
            proper_dihedrals,
            improper_dihedrals,
            adjacency,
        }
    }

    /// Identify aromatic atoms based on connectivity (heuristic)
    pub fn compute_aromaticity(&self, elements: &[String]) -> Vec<bool> {
        let mut is_aromatic = vec![false; elements.len()];

        for (i, element) in elements.iter().enumerate() {
            let neighbors = self.adjacency.get(&i).map(|v| v.len()).unwrap_or(0);

            // Heuristic: sp2 hybridized atoms (C, N) in 5 or 6 membered rings
            let possible_aromatic = match element.to_uppercase().as_str() {
                "C" => neighbors == 3,
                "N" => neighbors == 2 || neighbors == 3,
                _ => false,
            };

            if possible_aromatic && self.is_in_ring(i, 6) {
                is_aromatic[i] = true;
            }
        }
        is_aromatic
    }

    /// Check if an atom is part of a ring of size <= max_size
    pub fn is_in_ring(&self, atom_idx: usize, max_size: usize) -> bool {
        let mut visited = HashSet::new();
        visited.insert(atom_idx);

        if let Some(neighbors) = self.adjacency.get(&atom_idx) {
            for &next in neighbors {
                visited.insert(next);
                // Start DFS from neighbor, looking for path back to atom_idx
                if self.dfs_ring_search(atom_idx, next, atom_idx, 1, max_size, &mut visited) {
                    return true;
                }
                visited.remove(&next);
            }
        }
        false
    }

    /// Generate all unique angles from adjacency list
    pub fn generate_angles(adjacency: &HashMap<usize, Vec<usize>>) -> Vec<Angle> {
        let mut angles = HashSet::new();

        // For each central atom j
        for (&j, neighbors) in adjacency {
            if neighbors.len() < 2 {
                continue;
            }

            // For each pair of neighbors (i, k)
            for (idx, &i) in neighbors.iter().enumerate() {
                for &k in neighbors.iter().skip(idx + 1) {
                    angles.insert(Angle::new(i, j, k));
                }
            }
        }

        angles.into_iter().collect()
    }

    /// Generate all unique proper dihedrals from adjacency list
    pub fn generate_proper_dihedrals(adjacency: &HashMap<usize, Vec<usize>>) -> Vec<Dihedral> {
        let mut dihedrals = HashSet::new();

        // For each central bond j-k
        for (&j, j_neighbors) in adjacency {
            for &k in j_neighbors {
                if j >= k {
                    continue; // Avoid duplicates
                }

                let k_neighbors = adjacency.get(&k).cloned().unwrap_or_default();

                // For each i bonded to j (and not k)
                for &i in j_neighbors {
                    if i == k {
                        continue;
                    }

                    // For each l bonded to k (and not j, not i)
                    for &l in &k_neighbors {
                        if l == j || l == i {
                            continue;
                        }

                        dihedrals.insert(Dihedral::new_proper(i, j, k, l));
                    }
                }
            }
        }

        dihedrals.into_iter().collect()
    }

    /// Generate improper dihedrals for planar groups (sp2 centers)
    pub fn generate_improper_dihedrals(
        adjacency: &HashMap<usize, Vec<usize>>,
        elements: &[String],
    ) -> Vec<Dihedral> {
        let mut impropers = Vec::new();

        // Impropers are typically on sp2 carbons (3 neighbors) and amide nitrogens
        for (&center, neighbors) in adjacency {
            if neighbors.len() != 3 {
                continue;
            }

            // Check if likely sp2 (C with 3 bonds, or N with 3 bonds)
            let elem = elements.get(center).map(|s| s.as_str()).unwrap_or("");
            if elem == "C" || elem == "N" {
                impropers.push(Dihedral::new_improper(
                    center,
                    neighbors[0],
                    neighbors[1],
                    neighbors[2],
                ));
            }
        }

        impropers
    }

    fn dfs_ring_search(
        &self,
        target: usize,
        current: usize,
        prev: usize,
        depth: usize,
        max_size: usize,
        visited: &mut HashSet<usize>,
    ) -> bool {
        if depth >= max_size {
            return false;
        }

        if let Some(neighbors) = self.adjacency.get(&current) {
            for &next in neighbors {
                if next == prev {
                    continue;
                }
                if next == target {
                    return depth >= 2;
                }

                if !visited.contains(&next) {
                    visited.insert(next);
                    if self.dfs_ring_search(target, next, current, depth + 1, max_size, visited) {
                        return true;
                    }
                    visited.remove(&next);
                }
            }
        }
        false
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_bond_canonical() {
        let b1 = Bond::new(5, 3);
        let b2 = Bond::new(3, 5);
        assert_eq!(b1, b2);
        assert_eq!(b1.i, 3);
        assert_eq!(b1.j, 5);
    }

    #[test]
    fn test_angle_canonical() {
        let a1 = Angle::new(5, 2, 3);
        let a2 = Angle::new(3, 2, 5);
        assert_eq!(a1, a2);
    }

    #[test]
    fn test_methane_topology() {
        // Methane: C at origin, 4 H around it
        let elements = vec![
            "C".to_string(),
            "H".to_string(),
            "H".to_string(),
            "H".to_string(),
            "H".to_string(),
        ];

        // 4 C-H bonds
        let bonds = vec![
            Bond::new(0, 1),
            Bond::new(0, 2),
            Bond::new(0, 3),
            Bond::new(0, 4),
        ];

        let topo = Topology::new(bonds, &elements);

        // 4 C-H bonds
        assert_eq!(topo.bonds.len(), 4);

        // 6 angles (H-C-H, choose 2 from 4 hydrogens = 6)
        assert_eq!(topo.angles.len(), 6);

        // No proper dihedrals (need 4-atom chain)
        assert_eq!(topo.proper_dihedrals.len(), 0);
    }

    #[test]
    fn test_ethane_topology() {
        // Simplified ethane: C-C with 3 H each
        let elements = vec![
            "C".to_string(),
            "C".to_string(),
            "H".to_string(),
            "H".to_string(),
            "H".to_string(),
            "H".to_string(),
        ];

        // Bonds: C1-C2, C1-H1, C1-H2, C2-H3, C2-H4
        let bonds = vec![
            Bond::new(0, 1),
            Bond::new(0, 2),
            Bond::new(0, 3),
            Bond::new(1, 4),
            Bond::new(1, 5),
        ];

        let topo = Topology::new(bonds, &elements);

        // Should have 5 bonds
        assert_eq!(topo.bonds.len(), 5);

        // Should have angles (H1-C1-C2, H2-C1-C2, H1-C1-H2, H3-C2-C1, H4-C2-C1, H3-C2-H4)
        assert_eq!(topo.angles.len(), 6);

        // Should have proper dihedrals (H1-C1-C2-H3, H1-C1-C2-H4, H2-C1-C2-H3, H2-C1-C2-H4)
        assert_eq!(topo.proper_dihedrals.len(), 4);
    }
}

//! Force field data types for molecular dynamics.
//!
//! This module contains all the data structures used to represent
//! force field parameters parsed from OpenMM-style XML files.
//!
//! Note: Some fields are parsed but not yet fully utilized in Python API.

#![allow(dead_code)]

use std::collections::HashMap;

/// Atom type definition from the force field
#[derive(Debug, Clone)]
pub struct AtomType {
    /// Unique name of the atom type (e.g., "protein-C", "gaff-ca")
    pub name: String,
    /// Atom class for parameter lookup (e.g., "protein-C")
    pub class: String,
    /// Element symbol (e.g., "C", "N", "O")
    pub element: String,
    /// Atomic mass in atomic mass units (Da)
    pub mass: f32,
    /// Partial charge (optional, often defined in residue templates instead)
    pub charge: Option<f32>,
}

/// Atom within a residue template
#[derive(Debug, Clone)]
pub struct ResidueAtom {
    /// Atom name within the residue (e.g., "CA", "N", "O")
    pub name: String,
    /// Atom type for parameter lookup
    pub atom_type: String,
    /// Partial charge in elementary charge units (optional)
    pub charge: Option<f32>,
}

/// Residue template defining the topology of a residue
#[derive(Debug, Clone)]
pub struct ResidueTemplate {
    /// Residue name (3-letter code, e.g., "ALA", "GLY")
    pub name: String,
    /// Atoms in the residue
    pub atoms: Vec<ResidueAtom>,
    /// Internal bonds as (atom_name1, atom_name2) pairs
    pub bonds: Vec<(String, String)>,
    /// External bond connection points
    pub external_bonds: Vec<String>,
    /// Override priority (for N/C-terminal variants)
    pub override_level: Option<u32>,
}

/// Harmonic bond parameters: V(r) = k/2 * (r - r0)^2
#[derive(Debug, Clone)]
pub struct HarmonicBondParam {
    /// Atom type/class 1
    pub class1: String,
    /// Atom type/class 2
    pub class2: String,
    /// Force constant in kJ/mol/nm^2
    pub k: f32,
    /// Equilibrium bond length in nm
    pub length: f32,
}

/// Harmonic angle parameters: V(θ) = k/2 * (θ - θ0)^2
#[derive(Debug, Clone)]
pub struct HarmonicAngleParam {
    /// Atom type/class 1
    pub class1: String,
    /// Atom type/class 2 (central atom)
    pub class2: String,
    /// Atom type/class 3
    pub class3: String,
    /// Force constant in kJ/mol/rad^2
    pub k: f32,
    /// Equilibrium angle in radians
    pub angle: f32,
}

/// Periodic torsion (dihedral) term
#[derive(Debug, Clone)]
pub struct TorsionTerm {
    /// Periodicity (1, 2, 3, ...)
    pub periodicity: u32,
    /// Phase offset in radians
    pub phase: f32,
    /// Force constant in kJ/mol
    pub k: f32,
}

/// Proper torsion parameters for dihedrals
#[derive(Debug, Clone)]
pub struct ProperTorsionParam {
    /// Atom type/class 1
    pub class1: String,
    /// Atom type/class 2
    pub class2: String,
    /// Atom type/class 3
    pub class3: String,
    /// Atom type/class 4
    pub class4: String,
    /// Torsion terms (can have multiple periodicities)
    pub terms: Vec<TorsionTerm>,
}

/// Improper torsion parameters (for planarity)
#[derive(Debug, Clone)]
pub struct ImproperTorsionParam {
    /// Atom type/class 1
    pub class1: String,
    /// Atom type/class 2 (central atom)
    pub class2: String,
    /// Atom type/class 3
    pub class3: String,
    /// Atom type/class 4
    pub class4: String,
    /// Torsion terms
    pub terms: Vec<TorsionTerm>,
}

/// Nonbonded (Lennard-Jones) parameters per atom type
#[derive(Debug, Clone)]
pub struct NonbondedParam {
    /// Atom type this applies to
    pub atom_type: String,
    /// Charge in elementary charge units
    pub charge: f32,
    /// LJ sigma parameter in nm
    pub sigma: f32,
    /// LJ epsilon parameter in kJ/mol
    pub epsilon: f32,
}

/// Nonbonded 1-4 exception parameters (overrides scaling)
#[derive(Debug, Clone)]
pub struct NonbondedException {
    /// Atom type 1
    pub type1: String,
    /// Atom type 2
    pub type2: String,
    /// Charge product in elementary charge units squared
    pub charge_prod: f32,
    /// LJ sigma in nm
    pub sigma: f32,
    /// LJ epsilon in kJ/mol
    pub epsilon: f32,
}

/// GBSA-OBC implicit solvent parameters
#[derive(Debug, Clone)]
pub struct GBSAOBCParam {
    /// Atom type this applies to
    pub atom_type: String,
    /// Atomic radius in nm
    pub radius: f32,
    /// Scaling factor
    pub scale: f32,
}

/// CMAP torsion correction data
#[derive(Debug, Clone)]
pub struct CMAPData {
    /// Map index to energy grid
    pub maps: Vec<CMAPGrid>,
    /// Torsion definitions (which atom types use which map)
    pub torsions: Vec<CMAPTorsion>,
}

/// CMAP energy grid (typically 24x24)
#[derive(Debug, Clone)]
pub struct CMAPGrid {
    /// Grid size (e.g., 24)
    pub size: usize,
    /// Energy values in kJ/mol, row-major order
    pub energies: Vec<f32>,
}

/// CMAP torsion assignment
#[derive(Debug, Clone)]
pub struct CMAPTorsion {
    /// Five atom types defining the two overlapping dihedrals
    pub class1: String,
    pub type2: String,
    pub type3: String,
    pub type4: String,
    pub class5: String,
    /// Index into CMAPData.maps
    pub map_index: usize,
}

/// Complete parsed force field
#[derive(Debug, Clone)]
pub struct ForceField {
    /// Force field name/identifier
    pub name: String,

    /// Atom type definitions
    pub atom_types: Vec<AtomType>,

    /// Residue templates
    pub residue_templates: Vec<ResidueTemplate>,

    /// Harmonic bond parameters (class1-class2 → param)
    pub harmonic_bonds: Vec<HarmonicBondParam>,

    /// Harmonic angle parameters
    pub harmonic_angles: Vec<HarmonicAngleParam>,

    /// Proper torsion parameters
    pub proper_torsions: Vec<ProperTorsionParam>,

    /// Improper torsion parameters
    pub improper_torsions: Vec<ImproperTorsionParam>,

    /// Nonbonded parameters (indexed by atom type)
    pub nonbonded_params: Vec<NonbondedParam>,

    /// GBSA-OBC implicit solvent parameters
    pub gbsa_obc_params: Vec<GBSAOBCParam>,

    /// Nonbonded exceptions (1-4 overrides)
    pub exceptions: Vec<NonbondedException>,

    /// Global 1-4 scaling factors
    pub lj14scale: f32,
    pub coulomb14scale: f32,

    /// CMAP correction data (optional)
    pub cmap_data: Option<CMAPData>,

    // === Lookup tables for fast access ===
    /// Atom type name → index
    pub atom_type_map: HashMap<String, usize>,

    /// Residue name → template index
    pub residue_map: HashMap<String, usize>,
}

impl ForceField {
    /// Create an empty force field
    pub fn new(name: String) -> Self {
        Self {
            name,
            atom_types: Vec::new(),
            residue_templates: Vec::new(),
            harmonic_bonds: Vec::new(),
            harmonic_angles: Vec::new(),
            proper_torsions: Vec::new(),
            improper_torsions: Vec::new(),
            nonbonded_params: Vec::new(),
            gbsa_obc_params: Vec::new(),
            exceptions: Vec::new(),
            lj14scale: 0.5,           // Default AMBER
            coulomb14scale: 0.833333, // Default AMBER
            cmap_data: None,
            atom_type_map: HashMap::new(),
            residue_map: HashMap::new(),
        }
    }

    /// Build lookup indices after parsing
    pub fn build_indices(&mut self) {
        self.atom_type_map = self
            .atom_types
            .iter()
            .enumerate()
            .map(|(i, at)| (at.name.clone(), i))
            .collect();

        self.residue_map = self
            .residue_templates
            .iter()
            .enumerate()
            .map(|(i, rt)| (rt.name.clone(), i))
            .collect();
    }

    /// Get residue template by name
    pub fn get_residue(&self, name: &str) -> Option<&ResidueTemplate> {
        self.residue_map
            .get(name)
            .map(|&i| &self.residue_templates[i])
    }

    /// Get atom type by name
    pub fn get_atom_type(&self, name: &str) -> Option<&AtomType> {
        self.atom_type_map.get(name).map(|&i| &self.atom_types[i])
    }
}

