//! XML parser for OpenMM-style force field files.
//!
//! Parses force field XML files (e.g., protein.ff19SB.xml) into
//! the ForceField data structure.

use std::fs::File;
use std::io::BufReader;
use std::path::Path;

use quick_xml::events::{BytesStart, Event};
use quick_xml::Reader;
use thiserror::Error;

use super::types::*;

/// Errors that can occur during force field parsing
#[derive(Error, Debug)]
pub enum ParseError {
    #[error("IO error: {0}")]
    Io(#[from] std::io::Error),

    #[error("XML parsing error: {0}")]
    Xml(#[from] quick_xml::Error),

    #[error("Missing required attribute: {0}")]
    MissingAttribute(String),

    #[error("Invalid attribute value: {0}")]
    InvalidValue(String),

    #[error("UTF-8 decode error: {0}")]
    Utf8(#[from] std::str::Utf8Error),

    #[error("Feature not implemented: {0}")]
    NotImplemented(String),
}

/// Parse a force field XML file
pub fn parse_forcefield_xml(path: &str) -> Result<ForceField, ParseError> {
    let path = Path::new(path);
    let file = File::open(path)?;
    let reader = BufReader::new(file);

    let name = path
        .file_stem()
        .and_then(|s| s.to_str())
        .unwrap_or("unknown")
        .to_string();

    parse_xml_reader(reader, name)
}

/// Parse from any reader
fn parse_xml_reader<R: std::io::BufRead>(
    reader: R,
    name: String,
) -> Result<ForceField, ParseError> {
    let mut xml_reader = Reader::from_reader(reader);
    xml_reader.trim_text(true);

    let mut ff = ForceField::new(name);
    let mut buf = Vec::new();

    loop {
        match xml_reader.read_event_into(&mut buf) {
            Ok(Event::Start(ref e)) => match e.name().as_ref() {
                b"AtomTypes" => parse_atom_types(&mut xml_reader, &mut ff)?,
                b"Residues" => parse_residues(&mut xml_reader, &mut ff)?,
                b"HarmonicBondForce" => parse_harmonic_bonds(&mut xml_reader, &mut ff)?,
                b"HarmonicAngleForce" => parse_harmonic_angles(&mut xml_reader, &mut ff)?,
                b"PeriodicTorsionForce" => parse_periodic_torsions(&mut xml_reader, &mut ff)?,
                b"NonbondedForce" => parse_nonbonded(&mut xml_reader, &mut ff, e)?,
                b"GBSAOBCForce" => parse_gbsa_obc(&mut xml_reader, &mut ff)?,
                b"CMAPTorsionForce" => parse_cmap(&mut xml_reader, &mut ff)?,
                b"AmoebaMultipoleForce" | b"MultipoleForce" => {
                    return Err(ParseError::NotImplemented(
                        "MultipoleForce (AMOEBA) is not yet supported".to_string(),
                    ));
                }
                b"AmoebaVdwForce" => {
                    return Err(ParseError::NotImplemented(
                        "AmoebaVdwForce is not yet supported".to_string(),
                    ));
                }
                _ => {}
            },
            Ok(Event::Eof) => break,
            Err(e) => return Err(ParseError::Xml(e)),
            _ => {}
        }
        buf.clear();
    }

    ff.build_indices();
    Ok(ff)
}

/// Helper to get a required attribute as string
fn get_attr(e: &BytesStart, name: &[u8]) -> Result<String, ParseError> {
    for attr in e.attributes().flatten() {
        if attr.key.as_ref() == name {
            return Ok(String::from_utf8_lossy(&attr.value).to_string());
        }
    }
    Err(ParseError::MissingAttribute(
        String::from_utf8_lossy(name).to_string(),
    ))
}

/// Helper to get an optional attribute as string
fn get_attr_opt(e: &BytesStart, name: &[u8]) -> Option<String> {
    for attr in e.attributes().flatten() {
        if attr.key.as_ref() == name {
            return Some(String::from_utf8_lossy(&attr.value).to_string());
        }
    }
    None
}

/// Helper to get one of two attributes (e.g. "class1" or "type1")
fn get_attr_either(e: &BytesStart, name1: &[u8], name2: &[u8]) -> Result<String, ParseError> {
    get_attr_opt(e, name1)
        .or_else(|| get_attr_opt(e, name2))
        .ok_or_else(|| {
            ParseError::MissingAttribute(format!(
                "{} or {}",
                String::from_utf8_lossy(name1),
                String::from_utf8_lossy(name2)
            ))
        })
}

/// Helper to parse f32 attribute
fn get_attr_f32(e: &BytesStart, name: &[u8]) -> Result<f32, ParseError> {
    let val = get_attr(e, name)?;
    val.parse::<f32>()
        .map_err(|_| ParseError::InvalidValue(format!("Cannot parse '{}' as f32", val)))
}

/// Helper to parse optional f32 attribute
fn get_attr_f32_opt(e: &BytesStart, name: &[u8]) -> Option<f32> {
    get_attr_opt(e, name).and_then(|v| v.parse().ok())
}

/// Helper to parse u32 attribute
fn get_attr_u32(e: &BytesStart, name: &[u8]) -> Result<u32, ParseError> {
    let val = get_attr(e, name)?;
    val.parse::<u32>()
        .map_err(|_| ParseError::InvalidValue(format!("Cannot parse '{}' as u32", val)))
}

/// Parse <AtomTypes> section
fn parse_atom_types<R: std::io::BufRead>(
    reader: &mut Reader<R>,
    ff: &mut ForceField,
) -> Result<(), ParseError> {
    let mut buf = Vec::new();

    loop {
        match reader.read_event_into(&mut buf) {
            Ok(Event::Empty(ref e)) if e.name().as_ref() == b"Type" => {
                let atom_type = AtomType {
                    name: get_attr(e, b"name")?,
                    class: get_attr_either(e, b"class", b"type")
                        .unwrap_or_else(|_| get_attr(e, b"name").unwrap_or_default()),
                    element: get_attr_opt(e, b"element").unwrap_or_default(),
                    mass: get_attr_f32(e, b"mass")?,
                    charge: get_attr_f32_opt(e, b"charge"),
                };
                ff.atom_types.push(atom_type);
            }
            Ok(Event::End(ref e)) if e.name().as_ref() == b"AtomTypes" => break,
            Ok(Event::Eof) => break,
            Err(e) => return Err(ParseError::Xml(e)),
            _ => {}
        }
        buf.clear();
    }

    Ok(())
}

/// Parse <Residues> section
fn parse_residues<R: std::io::BufRead>(
    reader: &mut Reader<R>,
    ff: &mut ForceField,
) -> Result<(), ParseError> {
    let mut buf = Vec::new();

    loop {
        match reader.read_event_into(&mut buf) {
            Ok(Event::Start(ref e)) if e.name().as_ref() == b"Residue" => {
                let template = parse_single_residue(reader, e)?;
                ff.residue_templates.push(template);
            }
            Ok(Event::End(ref e)) if e.name().as_ref() == b"Residues" => break,
            Ok(Event::Eof) => break,
            Err(e) => return Err(ParseError::Xml(e)),
            _ => {}
        }
        buf.clear();
    }

    Ok(())
}

/// Parse a single <Residue> element
fn parse_single_residue<R: std::io::BufRead>(
    reader: &mut Reader<R>,
    start: &BytesStart,
) -> Result<ResidueTemplate, ParseError> {
    let name = get_attr(start, b"name")?;
    let override_level = get_attr_opt(start, b"override").and_then(|v| v.parse().ok());

    let mut atoms = Vec::new();
    let mut bonds = Vec::new();
    let mut external_bonds = Vec::new();

    let mut buf = Vec::new();

    loop {
        match reader.read_event_into(&mut buf) {
            Ok(Event::Empty(ref e)) => match e.name().as_ref() {
                b"Atom" => {
                    atoms.push(ResidueAtom {
                        name: get_attr(e, b"name")?,
                        atom_type: get_attr(e, b"type")?,
                        charge: get_attr_f32_opt(e, b"charge"),
                    });
                }
                b"Bond" => {
                    // Try "atomName1"/"atomName2" first
                    let n1 = get_attr_opt(e, b"atomName1");
                    let n2 = get_attr_opt(e, b"atomName2");

                    if let (Some(n1), Some(n2)) = (n1, n2) {
                        bonds.push((n1, n2));
                    } else {
                        // Try "from"/"to" (indices or names)
                        let from = get_attr(e, b"from")?;
                        let to = get_attr(e, b"to")?;

                        // Try to parse as indices
                        let name1 = if let Ok(idx) = from.parse::<usize>() {
                            atoms.get(idx).map(|a| a.name.clone()).ok_or_else(|| {
                                ParseError::InvalidValue(format!(
                                    "Bond index {} out of bounds",
                                    idx
                                ))
                            })?
                        } else {
                            from
                        };

                        let name2 = if let Ok(idx) = to.parse::<usize>() {
                            atoms.get(idx).map(|a| a.name.clone()).ok_or_else(|| {
                                ParseError::InvalidValue(format!(
                                    "Bond index {} out of bounds",
                                    idx
                                ))
                            })?
                        } else {
                            to
                        };

                        bonds.push((name1, name2));
                    }
                }
                b"ExternalBond" => {
                    // Try "atomName" first
                    if let Some(name) = get_attr_opt(e, b"atomName") {
                        external_bonds.push(name);
                    } else {
                        // Try "from" (index or name)
                        let from = get_attr(e, b"from")?;

                        // Try to parse as index
                        let name = if let Ok(idx) = from.parse::<usize>() {
                            atoms.get(idx).map(|a| a.name.clone()).ok_or_else(|| {
                                ParseError::InvalidValue(format!(
                                    "ExternalBond index {} out of bounds",
                                    idx
                                ))
                            })?
                        } else {
                            from
                        };

                        external_bonds.push(name);
                    }
                }
                _ => {}
            },
            Ok(Event::End(ref e)) if e.name().as_ref() == b"Residue" => break,
            Ok(Event::Eof) => break,
            Err(e) => return Err(ParseError::Xml(e)),
            _ => {}
        }
        buf.clear();
    }

    Ok(ResidueTemplate {
        name,
        atoms,
        bonds,
        external_bonds,
        override_level,
    })
}

/// Parse <HarmonicBondForce> section
fn parse_harmonic_bonds<R: std::io::BufRead>(
    reader: &mut Reader<R>,
    ff: &mut ForceField,
) -> Result<(), ParseError> {
    let mut buf = Vec::new();

    loop {
        match reader.read_event_into(&mut buf) {
            Ok(Event::Empty(ref e)) if e.name().as_ref() == b"Bond" => {
                ff.harmonic_bonds.push(HarmonicBondParam {
                    class1: get_attr_either(e, b"class1", b"type1")?,
                    class2: get_attr_either(e, b"class2", b"type2")?,
                    k: get_attr_f32(e, b"k")?,
                    length: get_attr_f32(e, b"length")?,
                });
            }
            Ok(Event::End(ref e)) if e.name().as_ref() == b"HarmonicBondForce" => break,
            Ok(Event::Eof) => break,
            Err(e) => return Err(ParseError::Xml(e)),
            _ => {}
        }
        buf.clear();
    }

    Ok(())
}

/// Parse <HarmonicAngleForce> section
fn parse_harmonic_angles<R: std::io::BufRead>(
    reader: &mut Reader<R>,
    ff: &mut ForceField,
) -> Result<(), ParseError> {
    let mut buf = Vec::new();

    loop {
        match reader.read_event_into(&mut buf) {
            Ok(Event::Empty(ref e)) if e.name().as_ref() == b"Angle" => {
                ff.harmonic_angles.push(HarmonicAngleParam {
                    class1: get_attr_either(e, b"class1", b"type1")?,
                    class2: get_attr_either(e, b"class2", b"type2")?,
                    class3: get_attr_either(e, b"class3", b"type3")?,
                    k: get_attr_f32(e, b"k")?,
                    angle: get_attr_f32(e, b"angle")?,
                });
            }
            Ok(Event::End(ref e)) if e.name().as_ref() == b"HarmonicAngleForce" => break,
            Ok(Event::Eof) => break,
            Err(e) => return Err(ParseError::Xml(e)),
            _ => {}
        }
        buf.clear();
    }

    Ok(())
}

/// Parse <PeriodicTorsionForce> section
fn parse_periodic_torsions<R: std::io::BufRead>(
    reader: &mut Reader<R>,
    ff: &mut ForceField,
) -> Result<(), ParseError> {
    let mut buf = Vec::new();

    loop {
        match reader.read_event_into(&mut buf) {
            Ok(Event::Empty(ref e)) => match e.name().as_ref() {
                b"Proper" => {
                    let torsion = parse_torsion_element(e)?;
                    ff.proper_torsions.push(ProperTorsionParam {
                        class1: torsion.0,
                        class2: torsion.1,
                        class3: torsion.2,
                        class4: torsion.3,
                        terms: torsion.4,
                    });
                }
                b"Improper" => {
                    let torsion = parse_torsion_element(e)?;
                    ff.improper_torsions.push(ImproperTorsionParam {
                        class1: torsion.0,
                        class2: torsion.1,
                        class3: torsion.2,
                        class4: torsion.3,
                        terms: torsion.4,
                    });
                }
                _ => {}
            },
            Ok(Event::End(ref e)) if e.name().as_ref() == b"PeriodicTorsionForce" => break,
            Ok(Event::Eof) => break,
            Err(e) => return Err(ParseError::Xml(e)),
            _ => {}
        }
        buf.clear();
    }

    Ok(())
}

/// Parse a torsion element with potentially multiple periodicities
fn parse_torsion_element(
    e: &BytesStart,
) -> Result<(String, String, String, String, Vec<TorsionTerm>), ParseError> {
    let class1 = get_attr_opt(e, b"class1")
        .or(get_attr_opt(e, b"type1"))
        .unwrap_or_default();
    let class2 = get_attr_opt(e, b"class2")
        .or(get_attr_opt(e, b"type2"))
        .unwrap_or_default();
    let class3 = get_attr_opt(e, b"class3")
        .or(get_attr_opt(e, b"type3"))
        .unwrap_or_default();
    let class4 = get_attr_opt(e, b"class4")
        .or(get_attr_opt(e, b"type4"))
        .unwrap_or_default();

    let mut terms = Vec::new();

    // Check for single term (periodicity, phase, k)
    if let (Some(periodicity), Some(phase), Some(k)) = (
        get_attr_f32_opt(e, b"periodicity"),
        get_attr_f32_opt(e, b"phase"),
        get_attr_f32_opt(e, b"k"),
    ) {
        terms.push(TorsionTerm {
            periodicity: periodicity as u32,
            phase,
            k,
        });
    }

    // Check for multiple terms (periodicity1, phase1, k1, etc.)
    for i in 1..=6 {
        let per_key = format!("periodicity{}", i);
        let phase_key = format!("phase{}", i);
        let k_key = format!("k{}", i);

        if let (Some(periodicity), Some(phase), Some(k)) = (
            get_attr_f32_opt(e, per_key.as_bytes()),
            get_attr_f32_opt(e, phase_key.as_bytes()),
            get_attr_f32_opt(e, k_key.as_bytes()),
        ) {
            terms.push(TorsionTerm {
                periodicity: periodicity as u32,
                phase,
                k,
            });
        }
    }

    Ok((class1, class2, class3, class4, terms))
}

/// Parse <NonbondedForce> section
///
/// Note: In some force fields (like ff19SB), atoms use "class" instead of "type",
/// and charges are defined per-residue rather than per-atom-type.
fn parse_nonbonded<R: std::io::BufRead>(
    reader: &mut Reader<R>,
    ff: &mut ForceField,
    e: &BytesStart,
) -> Result<(), ParseError> {
    ff.lj14scale = get_attr_f32_opt(e, b"lj14scale").unwrap_or(0.5);
    ff.coulomb14scale = get_attr_f32_opt(e, b"coulomb14scale").unwrap_or(0.833333);

    let mut buf = Vec::new();

    loop {
        match reader.read_event_into(&mut buf) {
            Ok(Event::Empty(ref e)) if e.name().as_ref() == b"Atom" => {
                // Try "type" first, fall back to "class"
                let atom_type = get_attr_opt(e, b"type")
                    .or_else(|| get_attr_opt(e, b"class"))
                    .ok_or_else(|| ParseError::MissingAttribute("type or class".to_string()))?;

                // Charge is optional (may be defined per-residue)
                let charge = get_attr_f32_opt(e, b"charge").unwrap_or(0.0);

                ff.nonbonded_params.push(NonbondedParam {
                    atom_type,
                    charge,
                    sigma: get_attr_f32(e, b"sigma")?,
                    epsilon: get_attr_f32(e, b"epsilon")?,
                });
            }
            Ok(Event::Empty(ref e)) if e.name().as_ref() == b"Exception" => {
                ff.exceptions.push(NonbondedException {
                    type1: get_attr(e, b"type1")?,
                    type2: get_attr(e, b"type2")?,
                    charge_prod: get_attr_f32(e, b"chargeProd")?,
                    sigma: get_attr_f32(e, b"sigma")?,
                    epsilon: get_attr_f32(e, b"epsilon")?,
                });
            }
            Ok(Event::End(ref e)) if e.name().as_ref() == b"NonbondedForce" => break,
            Ok(Event::Eof) => break,
            Err(e) => return Err(ParseError::Xml(e)),
            _ => {}
        }
        buf.clear();
    }

    Ok(())
}

/// Parse <GBSAOBCForce> section for implicit solvent
fn parse_gbsa_obc<R: std::io::BufRead>(
    reader: &mut Reader<R>,
    ff: &mut ForceField,
) -> Result<(), ParseError> {
    let mut buf = Vec::new();

    loop {
        match reader.read_event_into(&mut buf) {
            Ok(Event::Empty(ref e)) if e.name().as_ref() == b"Atom" => {
                ff.gbsa_obc_params.push(GBSAOBCParam {
                    atom_type: get_attr(e, b"type")?,
                    radius: get_attr_f32(e, b"radius")?,
                    scale: get_attr_f32(e, b"scale")?,
                });
            }
            Ok(Event::End(ref e)) if e.name().as_ref() == b"GBSAOBCForce" => break,
            Ok(Event::Eof) => break,
            Err(e) => return Err(ParseError::Xml(e)),
            _ => {}
        }
        buf.clear();
    }

    Ok(())
}

/// Parse <CMAPTorsionForce> section
fn parse_cmap<R: std::io::BufRead>(
    reader: &mut Reader<R>,
    ff: &mut ForceField,
) -> Result<(), ParseError> {
    let mut buf = Vec::new();
    let mut maps = Vec::new();
    let mut torsions = Vec::new();

    loop {
        match reader.read_event_into(&mut buf) {
            Ok(Event::Start(ref e)) if e.name().as_ref() == b"Map" => {
                // Read the grid data as text content
                let grid = parse_cmap_grid(reader)?;
                maps.push(grid);
            }
            Ok(Event::Empty(ref e)) if e.name().as_ref() == b"Torsion" => {
                torsions.push(CMAPTorsion {
                    class1: get_attr_either(e, b"class1", b"type1")?,
                    type2: get_attr_either(e, b"class2", b"type2")?,
                    type3: get_attr_either(e, b"class3", b"type3")?,
                    type4: get_attr_either(e, b"class4", b"type4")?,
                    class5: get_attr_either(e, b"class5", b"type5")?,
                    map_index: get_attr_u32(e, b"map")? as usize,
                });
            }
            Ok(Event::End(ref e)) if e.name().as_ref() == b"CMAPTorsionForce" => break,
            Ok(Event::Eof) => break,
            Err(e) => return Err(ParseError::Xml(e)),
            _ => {}
        }
        buf.clear();
    }

    if !maps.is_empty() {
        ff.cmap_data = Some(CMAPData { maps, torsions });
    }

    Ok(())
}

/// Parse CMAP grid content
fn parse_cmap_grid<R: std::io::BufRead>(reader: &mut Reader<R>) -> Result<CMAPGrid, ParseError> {
    let mut buf = Vec::new();
    let mut text_content = String::new();

    loop {
        match reader.read_event_into(&mut buf) {
            Ok(Event::Text(e)) => {
                text_content.push_str(&e.unescape().unwrap_or_default());
            }
            Ok(Event::End(ref e)) if e.name().as_ref() == b"Map" => break,
            Ok(Event::Eof) => break,
            Err(e) => return Err(ParseError::Xml(e)),
            _ => {}
        }
        buf.clear();
    }

    // Parse space-separated floats
    let energies: Vec<f32> = text_content
        .split_whitespace()
        .filter_map(|s| s.parse().ok())
        .collect();

    // Determine grid size (typically 24x24 = 576)
    let size = (energies.len() as f64).sqrt() as usize;

    Ok(CMAPGrid { size, energies })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_parse_atom_types_xml() {
        let xml = r#"<?xml version="1.0"?>
        <ForceField>
          <AtomTypes>
            <Type class="protein-C" element="C" mass="12.01" name="protein-C" />
            <Type class="protein-N" element="N" mass="14.01" name="protein-N" />
          </AtomTypes>
        </ForceField>"#;

        let ff = parse_xml_reader(xml.as_bytes(), "test".to_string()).unwrap();

        assert_eq!(ff.atom_types.len(), 2);
        assert_eq!(ff.atom_types[0].name, "protein-C");
        assert_eq!(ff.atom_types[0].mass, 12.01);
        assert_eq!(ff.atom_types[1].element, "N");
    }

    #[test]
    fn test_parse_residue_xml() {
        let xml = r#"<?xml version="1.0"?>
        <ForceField>
          <Residues>
            <Residue name="ALA">
              <Atom charge="-0.4157" name="N" type="protein-N" />
              <Atom charge="0.2719" name="H" type="protein-H" />
              <Bond atomName1="N" atomName2="H" />
              <ExternalBond atomName="N" />
            </Residue>
          </Residues>
        </ForceField>"#;

        let ff = parse_xml_reader(xml.as_bytes(), "test".to_string()).unwrap();

        assert_eq!(ff.residue_templates.len(), 1);
        assert_eq!(ff.residue_templates[0].name, "ALA");
        assert_eq!(ff.residue_templates[0].atoms.len(), 2);
        assert_eq!(ff.residue_templates[0].bonds.len(), 1);
        assert_eq!(ff.residue_templates[0].external_bonds.len(), 1);
    }

    #[test]
    fn test_parse_harmonic_bond_xml() {
        let xml = r#"<?xml version="1.0"?>
        <ForceField>
          <HarmonicBondForce>
            <Bond class1="protein-C" class2="protein-N" k="410031.0" length="0.1335" />
          </HarmonicBondForce>
        </ForceField>"#;

        let ff = parse_xml_reader(xml.as_bytes(), "test".to_string()).unwrap();

        assert_eq!(ff.harmonic_bonds.len(), 1);
        assert_eq!(ff.harmonic_bonds[0].k, 410031.0);
        assert_eq!(ff.harmonic_bonds[0].length, 0.1335);
    }

    #[test]
    fn test_parse_periodic_torsion_xml() {
        let xml = r#"<?xml version="1.0"?>
        <ForceField>
          <PeriodicTorsionForce>
            <Proper class1="C" class2="CA" class3="CA" class4="C" periodicity1="3" phase1="0" k1="1.0" />
            <Improper class1="N" class2="C" class3="CA" class4="O" periodicity1="2" phase1="3.14" k1="2.5" />
          </PeriodicTorsionForce>
        </ForceField>"#;

        let ff = parse_xml_reader(xml.as_bytes(), "test".to_string()).unwrap();

        assert_eq!(ff.proper_torsions.len(), 1);
        assert_eq!(ff.proper_torsions[0].terms[0].periodicity, 3);
        assert_eq!(ff.proper_torsions[0].terms[0].k, 1.0);

        assert_eq!(ff.improper_torsions.len(), 1);
        assert!((ff.improper_torsions[0].terms[0].phase - 3.14).abs() < 0.01);
    }

    #[test]
    fn test_parse_nonbonded_exceptions_xml() {
        let xml = r#"<?xml version="1.0"?>
        <ForceField>
          <NonbondedForce lj14scale="0.5" coulomb14scale="0.833333">
            <Atom type="C" sigma="0.3" epsilon="0.1" />
            <Exception type1="C" type2="N" chargeProd="0.5" sigma="0.2" epsilon="0.05" />
          </NonbondedForce>
        </ForceField>"#;

        let ff = parse_xml_reader(xml.as_bytes(), "test".to_string()).unwrap();

        assert_eq!(ff.nonbonded_params.len(), 1);
        assert_eq!(ff.nonbonded_params[0].sigma, 0.3);

        assert_eq!(ff.exceptions.len(), 1);
        assert_eq!(ff.exceptions[0].type1, "C");
        assert_eq!(ff.exceptions[0].charge_prod, 0.5);
    }

    #[test]
    fn test_parse_malformed_xml() {
        let xml = r#"<?xml version="1.0"?>
        <ForceField>
          <HarmonicBondForce>
            <Bond class1="A" k="not_a_float" length="0.1" />
          </HarmonicBondForce>
        </ForceField>"#;

        let res = parse_xml_reader(xml.as_bytes(), "test".to_string());
        assert!(res.is_err());
    }
}

//! Proxide Core Library
//!
//! Foundational data structures and chemical constants for protein parsing.

pub mod chem;
pub mod forcefield;
pub mod processing;
pub mod spec;
pub mod structure;
#[cfg(any(test, feature = "testing"))]
pub mod testing;

// Re-exports for convenience
pub use spec::*;
pub use structure::systems::*;
pub use processing::ProcessedStructure;
pub use forcefield::*;

//! Residue processing and grouping
//!
//! Groups atoms by residue and builds residue-level metadata
//!
//! Note: Some fields are used for debugging/future features.

#![allow(dead_code)]

use crate::chem::{build_resname_to_idx, UNK_RESTYPE_INDEX};
use crate::structure::RawAtomData;
use crate::spec::OutputFormatTarget;
use std::collections::HashMap;

// Using hardcoded constants for now to avoid circular dependencies during the refactor.
// They should be moved to a shared 'constants' crate eventually.
const DEFAULT_SIGMA: f32 = 3.5;
const DEFAULT_EPSILON: f32 = 0.1;

/// Residue identifier (unique combination of chain, resid, insertion code)
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct ResidueId {
    pub chain_id: String,
    pub res_id: i32,
    pub insertion_code: char,
}

/// Information about a single residue
#[derive(Debug, Clone)]
pub struct ResidueInfo {
    pub res_id: i32,
    pub res_name: String,
    pub res_type: usize, // Index into residue types (0-20)
    pub chain_id: String,
    pub insertion_code: char,
    pub start_atom: usize, // Index of first atom
    pub num_atoms: usize,  // Number of atoms in this residue
}

/// Information about a ligand
#[derive(Debug, Clone)]
pub struct LigandInfo {
    pub res_name: String,
    pub atom_indices: Vec<usize>,
    pub chain_id: String,
    pub res_id: i32,
}

/// Processed structure with residue-level organization
#[derive(Debug)]
pub struct ProcessedStructure {
    pub raw_atoms: RawAtomData,
    pub residue_info: Vec<ResidueInfo>,
    pub chain_indices: HashMap<String, usize>, // chain_id -> index

    // HETATM components
    pub ligand_groups: Vec<LigandInfo>,
    pub solvent_atoms: Vec<usize>,
    pub ion_atoms: Vec<usize>,

    // Per-atom molecule type: 0=protein, 1=ligand, 2=solvent, 3=ion
    pub molecule_type: Vec<i8>,

    pub num_residues: usize,
    pub num_chains: usize,
}

impl ProcessedStructure {
    /// Create a ProcessedStructure from RawAtomData
    pub fn from_raw(raw_atoms: RawAtomData) -> Result<Self, String> {
        if raw_atoms.num_atoms == 0 {
            return Err("No atoms in structure".to_string());
        }

        // Build residue ID to atom indices mapping
        let mut residue_atoms: HashMap<ResidueId, Vec<usize>> = HashMap::new();

        for i in 0..raw_atoms.num_atoms {
            let res_id = ResidueId {
                chain_id: raw_atoms.chain_ids[i].clone(),
                res_id: raw_atoms.res_ids[i],
                insertion_code: raw_atoms.insertion_codes[i],
            };

            residue_atoms.entry(res_id).or_default().push(i);
        }

        // Sort residues by chain and residue number
        let mut residue_ids: Vec<_> = residue_atoms.keys().cloned().collect();
        residue_ids.sort_by(|a, b| {
            a.chain_id
                .cmp(&b.chain_id)
                .then(a.res_id.cmp(&b.res_id))
                .then(a.insertion_code.cmp(&b.insertion_code))
        });

        // Initialize classification containers
        let mut residue_info = Vec::with_capacity(residue_ids.len());
        let mut ligand_groups = Vec::new();
        let mut solvent_atoms = Vec::new();
        let mut ion_atoms = Vec::new();
        let mut molecule_type = vec![0i8; raw_atoms.num_atoms];

        let resname_to_idx = build_resname_to_idx();
        // Common solvent residue names
        let solvent_names = ["HOH", "WAT", "TIP3", "SOL", "DOD"];

        for res_id in &residue_ids {
            let atom_indices = &residue_atoms[res_id];
            let start_atom = atom_indices[0];
            let res_name = &raw_atoms.res_names[start_atom];
            let is_hetatm = raw_atoms.is_hetatm[start_atom];

            if !is_hetatm {
                // Protein Residue (ATOM record)
                // Mark atoms as protein (0) - already 0 initialized but being explicit
                for &idx in atom_indices {
                    molecule_type[idx] = 0;
                }

                // Map residue name to type index
                let res_type = resname_to_idx
                    .get(&res_name.clone())
                    .copied()
                    .unwrap_or(UNK_RESTYPE_INDEX);

                residue_info.push(ResidueInfo {
                    res_id: res_id.res_id,
                    res_name: res_name.clone(),
                    res_type,
                    chain_id: res_id.chain_id.clone(),
                    insertion_code: res_id.insertion_code,
                    start_atom,
                    num_atoms: atom_indices.len(),
                });
            } else {
                // HETATM Processing
                let is_solvent = solvent_names.contains(&res_name.as_str());

                if is_solvent {
                    // Solvent (2)
                    for &idx in atom_indices {
                        molecule_type[idx] = 2;
                        solvent_atoms.push(idx);
                    }
                } else if atom_indices.len() == 1 && res_name.len() <= 2 {
                    // Heuristic: single atom, short name (e.g. "CL", "ZN") -> Ion (3)
                    let idx = atom_indices[0];
                    molecule_type[idx] = 3;
                    ion_atoms.push(idx);
                } else {
                    // Ligand (1)
                    for &idx in atom_indices {
                        molecule_type[idx] = 1;
                    }

                    ligand_groups.push(LigandInfo {
                        res_name: res_name.clone(),
                        atom_indices: atom_indices.clone(),
                        chain_id: res_id.chain_id.clone(),
                        res_id: res_id.res_id,
                    });
                }
            }
        }

        // Build chain index mapping based on protein residues
        // But also include chains from ligands/solvent if needed?
        // For now, let's keep chain indices mapped to all unique chain IDs encountered
        // in residue_ids (which includes everything)
        let mut chain_ids: Vec<_> = residue_ids.iter().map(|r| r.chain_id.clone()).collect();
        chain_ids.sort();
        chain_ids.dedup();

        let chain_indices: HashMap<String, usize> = chain_ids
            .iter()
            .enumerate()
            .map(|(i, chain)| (chain.clone(), i))
            .collect();

        // Compute counts before moving values
        let num_residues = residue_info.len();
        let num_chains = chain_indices.len();

        log::debug!(
            "Processed structure: {} atoms -> {} residues, {} ligands, {} solvent atoms",
            raw_atoms.num_atoms,
            num_residues,
            ligand_groups.len(),
            solvent_atoms.len()
        );

        Ok(ProcessedStructure {
            raw_atoms,
            residue_info,
            chain_indices,
            ligand_groups,
            solvent_atoms,
            ion_atoms,
            molecule_type,
            num_residues,
            num_chains,
        })
    }

    /// Get atom indices for a specific residue
    pub fn get_residue_atoms(&self, residue_idx: usize) -> Vec<usize> {
        if residue_idx >= self.residue_info.len() {
            return Vec::new();
        }

        let res = &self.residue_info[residue_idx];
        (res.start_atom..res.start_atom + res.num_atoms).collect()
    }

    /// Extract AlphaFold-style backbone coordinates (N, CA, C, CB, O)
    /// Returns (N_res, 5, 3) array. Missing atoms are NaN.
    pub fn extract_backbone_coords(
        &self,
        target: OutputFormatTarget,
    ) -> Vec<[[f32; 3]; 5]> {
        let mut backbone = vec![[[f32::NAN; 3]; 5]; self.num_residues];

        let (idx_cb, idx_o) = match target {
            OutputFormatTarget::General => (3, 4),
            OutputFormatTarget::Mpnn => (4, 3),
        };

        for (i, res) in self.residue_info.iter().enumerate() {
            for atom_idx in res.start_atom..(res.start_atom + res.num_atoms) {
                let name = &self.raw_atoms.atom_names[atom_idx];
                let coords = [
                    self.raw_atoms.coords[atom_idx * 3],
                    self.raw_atoms.coords[atom_idx * 3 + 1],
                    self.raw_atoms.coords[atom_idx * 3 + 2],
                ];

                // Map to 0..4 indices
                match name.as_str() {
                    "N" => backbone[i][0] = coords,
                    "CA" => backbone[i][1] = coords,
                    "C" => backbone[i][2] = coords,
                    "CB" => backbone[i][idx_cb] = coords,
                    "O" => backbone[i][idx_o] = coords,
                    _ => {}
                }
            }
        }
        backbone
    }

    /// Extract CA coordinates for neighbor search
    /// Returns (N_res, 3). Missing CA is NaN.
    pub fn extract_ca_coords(&self) -> Vec<[f32; 3]> {
        let mut ca_coords = vec![[f32::NAN; 3]; self.num_residues];

        for (i, res) in self.residue_info.iter().enumerate() {
            for atom_idx in res.start_atom..(res.start_atom + res.num_atoms) {
                if self.raw_atoms.atom_names[atom_idx] == "CA" {
                    ca_coords[i] = [
                        self.raw_atoms.coords[atom_idx * 3],
                        self.raw_atoms.coords[atom_idx * 3 + 1],
                        self.raw_atoms.coords[atom_idx * 3 + 2],
                    ];
                    break;
                }
            }
        }
        ca_coords
    }

    /// Extract all atom positions as (N_atoms, 3)
    pub fn extract_all_coords(&self) -> Vec<[f32; 3]> {
        let n = self.raw_atoms.num_atoms;
        let mut coords = Vec::with_capacity(n);
        for i in 0..n {
            coords.push([
                self.raw_atoms.coords[i * 3],
                self.raw_atoms.coords[i * 3 + 1],
                self.raw_atoms.coords[i * 3 + 2],
            ]);
        }
        coords
    }

    /// Extract charges at backbone positions (N_res * 5)
    pub fn extract_backbone_charges(&self, target: OutputFormatTarget) -> Vec<f32> {
        let mut values = vec![0.0f32; self.num_residues * 5];
        let (idx_cb, idx_o) = match target {
            OutputFormatTarget::General => (3, 4),
            OutputFormatTarget::Mpnn => (4, 3),
        };
        if let Some(ref data) = self.raw_atoms.charges {
            for (i, res) in self.residue_info.iter().enumerate() {
                for atom_idx in res.start_atom..(res.start_atom + res.num_atoms) {
                    if atom_idx >= data.len() {
                        continue;
                    }
                    let val = data[atom_idx];
                    match self.raw_atoms.atom_names[atom_idx].as_str() {
                        "N" => values[i * 5] = val,
                        "CA" => values[i * 5 + 1] = val,
                        "C" => values[i * 5 + 2] = val,
                        "CB" => values[i * 5 + idx_cb] = val,
                        "O" => values[i * 5 + idx_o] = val,
                        _ => {}
                    }
                }
            }
        }
        values
    }

    /// Extract sigmas at backbone positions (N_res * 5)
    pub fn extract_backbone_sigmas(&self, target: OutputFormatTarget) -> Vec<f32> {
        // Default sigma? Or 0.0?
        // Using DEFAULT_SIGMA if missing might be safer if used in VdW equation
        let mut values = vec![DEFAULT_SIGMA; self.num_residues * 5];
        let (idx_cb, idx_o) = match target {
            OutputFormatTarget::General => (3, 4),
            OutputFormatTarget::Mpnn => (4, 3),
        };
        if let Some(ref data) = self.raw_atoms.sigmas {
            for (i, res) in self.residue_info.iter().enumerate() {
                for atom_idx in res.start_atom..(res.start_atom + res.num_atoms) {
                    if atom_idx >= data.len() {
                        continue;
                    }
                    let val = data[atom_idx];
                    match self.raw_atoms.atom_names[atom_idx].as_str() {
                        "N" => values[i * 5] = val,
                        "CA" => values[i * 5 + 1] = val,
                        "C" => values[i * 5 + 2] = val,
                        "CB" => values[i * 5 + idx_cb] = val,
                        "O" => values[i * 5 + idx_o] = val,
                        _ => {}
                    }
                }
            }
        }
        values
    }

    /// Extract epsilons at backbone positions (N_res * 5)
    pub fn extract_backbone_epsilons(&self, target: OutputFormatTarget) -> Vec<f32> {
        let mut values = vec![DEFAULT_EPSILON; self.num_residues * 5];
        let (idx_cb, idx_o) = match target {
            OutputFormatTarget::General => (3, 4),
            OutputFormatTarget::Mpnn => (4, 3),
        };
        if let Some(ref data) = self.raw_atoms.epsilons {
            for (i, res) in self.residue_info.iter().enumerate() {
                for atom_idx in res.start_atom..(res.start_atom + res.num_atoms) {
                    if atom_idx >= data.len() {
                        continue;
                    }
                    let val = data[atom_idx];
                    match self.raw_atoms.atom_names[atom_idx].as_str() {
                        "N" => values[i * 5] = val,
                        "CA" => values[i * 5 + 1] = val,
                        "C" => values[i * 5 + 2] = val,
                        "CB" => values[i * 5 + idx_cb] = val,
                        "O" => values[i * 5 + idx_o] = val,
                        _ => {}
                    }
                }
            }
        }
        values
    }
}

/// Rebuild ProcessedStructure and Bonds by sorting atoms to ensure contiguous residues.
/// This is necessary after adding atoms (like Hydrogens) which are appended to the end.
pub fn rebuild_topology(
    structure: ProcessedStructure,
    bonds: Vec<[usize; 2]>,
) -> Result<(ProcessedStructure, Vec<[usize; 2]>), String> {
    let n = structure.raw_atoms.num_atoms;
    if n == 0 {
        return Ok((structure, bonds));
    }

    // 1. Create permutation
    let mut indices: Vec<usize> = (0..n).collect();

    // Sort key: (ChainID, ResID, AtomOrder/Index)
    indices.sort_by(|&a, &b| {
        let chain_a = &structure.raw_atoms.chain_ids[a];
        let chain_b = &structure.raw_atoms.chain_ids[b];
        let res_a = structure.raw_atoms.res_ids[a];
        let res_b = structure.raw_atoms.res_ids[b];

        chain_a.cmp(chain_b).then(res_a.cmp(&res_b)).then(a.cmp(&b)) // Stable relative order
    });

    // 2. Build mapping (Old -> New)
    let mut old_to_new = vec![0usize; n];
    for (new_idx, &old_idx) in indices.iter().enumerate() {
        old_to_new[old_idx] = new_idx;
    }

    // 3. Permute RawAtomData
    let old_raw = structure.raw_atoms;
    let mut new_raw = RawAtomData::new();
    new_raw.num_atoms = n;

    // Pre-allocate vectors
    // new_raw.ids removed - not a field
    // RawAtomData fields are: coords, atom_names, elements, serial_numbers, ...
    // Wait, check definition in mod.rs: "pub serial_numbers: Vec<i32>".
    // "pub res_ids: Vec<i32>".
    // I need to match fields exactly.

    new_raw.coords = Vec::with_capacity(n * 3);
    new_raw.atom_names = Vec::with_capacity(n);
    new_raw.elements = Vec::with_capacity(n);
    new_raw.serial_numbers = Vec::with_capacity(n);
    new_raw.alt_locs = Vec::with_capacity(n);
    new_raw.res_names = Vec::with_capacity(n);
    new_raw.res_ids = Vec::with_capacity(n);
    new_raw.insertion_codes = Vec::with_capacity(n);
    new_raw.chain_ids = Vec::with_capacity(n);
    new_raw.b_factors = Vec::with_capacity(n);
    new_raw.occupancy = Vec::with_capacity(n);
    new_raw.is_hetatm = Vec::with_capacity(n);

    // Manual loop over sorted indices
    for &idx in &indices {
        new_raw
            .coords
            .extend_from_slice(&old_raw.coords[idx * 3..idx * 3 + 3]);
        new_raw.atom_names.push(old_raw.atom_names[idx].clone());
        new_raw.elements.push(old_raw.elements[idx].clone());
        new_raw.serial_numbers.push(old_raw.serial_numbers[idx]);
        new_raw.alt_locs.push(old_raw.alt_locs[idx]);
        new_raw.res_names.push(old_raw.res_names[idx].clone());
        new_raw.res_ids.push(old_raw.res_ids[idx]);
        new_raw.insertion_codes.push(old_raw.insertion_codes[idx]);
        new_raw.chain_ids.push(old_raw.chain_ids[idx].clone());
        new_raw.b_factors.push(old_raw.b_factors[idx]);
        new_raw.occupancy.push(old_raw.occupancy[idx]);
        new_raw.is_hetatm.push(old_raw.is_hetatm[idx]);

        if let Some(ref c) = old_raw.charges {
            if new_raw.charges.is_none() {
                new_raw.charges = Some(Vec::with_capacity(n));
            }
            new_raw.charges.as_mut().unwrap().push(c[idx]);
        }
        if let Some(ref r) = old_raw.radii {
            if new_raw.radii.is_none() {
                new_raw.radii = Some(Vec::with_capacity(n));
            }
            new_raw.radii.as_mut().unwrap().push(r[idx]);
        }
        if let Some(ref s) = old_raw.sigmas {
            if new_raw.sigmas.is_none() {
                new_raw.sigmas = Some(Vec::with_capacity(n));
            }
            new_raw.sigmas.as_mut().unwrap().push(s[idx]);
        }
        if let Some(ref e) = old_raw.epsilons {
            if new_raw.epsilons.is_none() {
                new_raw.epsilons = Some(Vec::with_capacity(n));
            }
            new_raw.epsilons.as_mut().unwrap().push(e[idx]);
        }
    }

    // 4. Remap Bonds
    let mut new_bonds = Vec::with_capacity(bonds.len());
    for bond in bonds {
        let (i, j) = (bond[0], bond[1]);
        if i < n && j < n {
            new_bonds.push([old_to_new[i], old_to_new[j]]);
        }
    }

    // 5. Build new ProcessedStructure
    let new_structure = ProcessedStructure::from_raw(new_raw)?;

    Ok((new_structure, new_bonds))
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::structure::AtomRecord;

    #[test]
    fn test_residue_grouping() {
        let mut raw = RawAtomData::with_capacity(6);

        // Add 2 residues (ALA and GLY) with 3 atoms each
        for i in 0..3 {
            raw.add_atom(AtomRecord {
                serial: i + 1,
                atom_name: if i == 0 {
                    "N".to_string()
                } else if i == 1 {
                    "CA".to_string()
                } else {
                    "C".to_string()
                },
                alt_loc: ' ',
                res_name: "ALA".to_string(),
                chain_id: "A".to_string(),
                res_seq: 1,
                i_code: ' ',
                x: i as f32,
                y: 0.0,
                z: 0.0,
                occupancy: 1.0,
                temp_factor: 20.0,
                element: "C".to_string(),
                charge: None,
                radius: None,
                is_hetatm: false,
            });
        }

        for i in 0..3 {
            raw.add_atom(AtomRecord {
                serial: i + 4,
                atom_name: if i == 0 {
                    "N".to_string()
                } else if i == 1 {
                    "CA".to_string()
                } else {
                    "C".to_string()
                },
                alt_loc: ' ',
                res_name: "GLY".to_string(),
                chain_id: "A".to_string(),
                res_seq: 2,
                i_code: ' ',
                x: i as f32 + 3.0,
                y: 0.0,
                z: 0.0,
                occupancy: 1.0,
                temp_factor: 20.0,
                element: "C".to_string(),
                charge: None,
                radius: None,
                is_hetatm: false,
            });
        }

        let processed = ProcessedStructure::from_raw(raw).unwrap();

        assert_eq!(processed.num_residues, 2);
        assert_eq!(processed.num_chains, 1);
        assert_eq!(processed.residue_info[0].res_name, "ALA");
        assert_eq!(processed.residue_info[1].res_name, "GLY");
        assert_eq!(processed.residue_info[0].num_atoms, 3);
        assert_eq!(processed.residue_info[1].num_atoms, 3);
    }

    #[test]
    fn test_multi_chain() {
        let mut raw = RawAtomData::with_capacity(2);

        raw.add_atom(AtomRecord {
            serial: 1,
            atom_name: "CA".to_string(),
            alt_loc: ' ',
            res_name: "ALA".to_string(),
            chain_id: "A".to_string(),
            res_seq: 1,
            i_code: ' ',
            x: 0.0,
            y: 0.0,
            z: 0.0,
