//! Output specification for structure formatting
//!
//! Defines the OutputSpec struct that controls how structures are formatted
//! and what optional processing steps should be applied.

use proxide_units::UnitSystem;

/// Coordinate format options
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum CoordFormat {
    /// Atom37 format: (N_res, 37, 3) - standard AlphaFold representation
    Atom37,
    /// Atom14 format: (N_res, 14, 3) - reduced representation
    Atom14,
    /// Full format: all atoms with padding
    Full,
    /// Backbone only: (N_res, 4, 3) - N, CA, C, O
    BackboneOnly,
}

/// Output format target for backbone ordering
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum OutputFormatTarget {
    /// General format: 0:N, 1:CA, 2:C, 3:CB, 4:O (standard Atom37)
    #[default]
    General,
    /// MPNN format: 0:N, 1:CA, 2:C, 3:O, 4:CB (PrxteinMPNN compatible)
    Mpnn,
}

impl std::str::FromStr for OutputFormatTarget {
    type Err = String;
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        match s.to_lowercase().as_str() {
            "general" => Ok(Self::General),
            "mpnn" => Ok(Self::Mpnn),
            _ => Err(format!(
                "Invalid output_format_target: {}. Must be 'general' or 'mpnn'",
                s
            )),
        }
    }
}

/// Error handling mode for missing atoms/residues
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ErrorMode {
    /// Log warnings and continue
    Warn,
    /// Skip problematic atoms/residues silently
    Skip,
    /// Fail entire structure on error
    Fail,
}

/// How to handle missing residue templates during parameterization
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum MissingResidueMode {
    /// Skip residue and log warning
    SkipWarn,
    /// Fail with error
    #[default]
    Fail,
    /// Try GAFF fallback (future - not implemented)
    GaffFallback,
    /// Match closest residue by shared atom names
    ClosestMatch,
}

/// Source for hydrogen atom placement
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum HydrogenSource {
    /// Use force field templates first, fallback to fragment library
    #[default]
    ForceFieldFirst,
    /// Use fragment library only (geometric placement via Kabsch)
    FragmentLibrary,
    /// Use force field templates only (fail if not defined)
    ForceFieldOnly,
}

/// Output specification for structure formatting
#[derive(Debug, Clone)]
pub struct OutputSpec {
    // Format
    pub coord_format: CoordFormat,
    pub output_format_target: String,

    // Filtering
    pub models: Option<Vec<usize>>,
    pub chains: Option<Vec<String>>,
    pub remove_hetatm: bool,
    pub include_hetatm: bool,
    pub remove_solvent: bool,
    pub residue_range: Option<(i32, i32)>,

    // Processing
    pub add_hydrogens: bool,
    pub hydrogen_source: HydrogenSource,
    pub relax_hydrogens: bool,
    pub relax_max_iterations: Option<usize>,
    pub infer_bonds: bool,

    // Geometry Features
    pub compute_rbf: bool,
    pub rbf_num_neighbors: usize,

    // Physics Features
    pub compute_electrostatics: bool,
    pub electrostatics_noise: Option<f32>,
    pub compute_vdw: bool,
    pub parameterize_md: bool,
    pub force_field: Option<String>,
    pub auto_terminal_caps: bool,
    pub missing_residue_mode: MissingResidueMode,

    // Environment
    pub ph: Option<f32>,

    // Optional fields
    pub include_b_factors: bool,
    pub include_occupancy: bool,

    // Error handling
    pub error_mode: ErrorMode,

    // Performance
    pub enable_caching: bool,

    // Unit system
    pub unit_system: UnitSystem,
}

impl Default for OutputSpec {
    fn default() -> Self {
        Self {
            coord_format: CoordFormat::Atom37,
            output_format_target: "general".to_string(),
            models: None,
            chains: None,
            remove_hetatm: false,
            include_hetatm: false,
            remove_solvent: true,
            residue_range: None,
            add_hydrogens: false,
            hydrogen_source: HydrogenSource::ForceFieldFirst,
            relax_hydrogens: false,
            relax_max_iterations: None,
            infer_bonds: false,
            compute_rbf: false,
            rbf_num_neighbors: 30,
            compute_electrostatics: false,
            electrostatics_noise: None,
            compute_vdw: false,
            parameterize_md: false,
            force_field: None,
            auto_terminal_caps: true,
            missing_residue_mode: MissingResidueMode::Fail,
            ph: Some(7.0),
            include_b_factors: false,
            include_occupancy: false,
            error_mode: ErrorMode::Warn,
            enable_caching: false,
            unit_system: UnitSystem::Amber,
        }
    }
}

//! Core data structures for protein parsing
//!
//! This module defines Rust structures for raw atom data
//! matching biotite's AtomArray format.
//!
//! Note: Some utilities like with_capacity are for optional optimization.

#![allow(dead_code)]

pub mod systems;
// Note: systems module is available but not re-exported to avoid unused import warnings
// Use structure::systems::* directly if needed

/// Raw atom data from PDB/mmCIF parsing
/// Matches biotite's AtomArray - variable-length, ALL atoms
#[derive(Clone, Debug)]
pub struct RawAtomData {
    /// Coordinates (N_atoms, 3) flattened
    pub coords: Vec<f32>,

    /// Atom names for each atom
    pub atom_names: Vec<String>,

    /// Element symbols for each atom
    pub elements: Vec<String>,

    /// Serial numbers from PDB
    pub serial_numbers: Vec<i32>,

    /// Alternate location indicators
    pub alt_locs: Vec<char>,

    /// Residue names (repeated per atom in that residue)
    pub res_names: Vec<String>,

    /// Residue sequence numbers (repeated per atom)
    pub res_ids: Vec<i32>,

    /// Insertion codes
    pub insertion_codes: Vec<char>,

    /// Chain IDs (as strings, repeated per atom)
    pub chain_ids: Vec<String>,

    /// Temperature factors (B-factors)
    pub b_factors: Vec<f32>,

    /// Occupancy values
    pub occupancy: Vec<f32>,

    /// Optional: charges (for PQR format or MD parameterization)
    pub charges: Option<Vec<f32>>,

    /// Optional: radii (for PQR format or GBSA)
    pub radii: Option<Vec<f32>>,

    /// Optional: LJ sigma parameters (from MD parameterization)
    pub sigmas: Option<Vec<f32>>,

    /// Optional: LJ epsilon parameters (from MD parameterization)
    pub epsilons: Option<Vec<f32>>,

    /// Total number of atoms
    pub num_atoms: usize,

    /// HETATM flag
    pub is_hetatm: Vec<bool>,
}

impl RawAtomData {
    /// Create a new empty RawAtomData
    pub fn new() -> Self {
        Self {
            coords: Vec::new(),
            atom_names: Vec::new(),
            elements: Vec::new(),
            serial_numbers: Vec::new(),
            alt_locs: Vec::new(),
            res_names: Vec::new(),
            res_ids: Vec::new(),
            insertion_codes: Vec::new(),
            chain_ids: Vec::new(),
            b_factors: Vec::new(),
            occupancy: Vec::new(),
            charges: None,
            radii: None,
            sigmas: None,
            epsilons: None,
            num_atoms: 0,
            is_hetatm: Vec::new(),
        }
    }

    /// Create with known capacity
    pub fn with_capacity(capacity: usize) -> Self {
        Self {
            coords: Vec::with_capacity(capacity * 3),
            atom_names: Vec::with_capacity(capacity),
            elements: Vec::with_capacity(capacity),
            serial_numbers: Vec::with_capacity(capacity),
            alt_locs: Vec::with_capacity(capacity),
            res_names: Vec::with_capacity(capacity),
            res_ids: Vec::with_capacity(capacity),
            insertion_codes: Vec::with_capacity(capacity),
            chain_ids: Vec::with_capacity(capacity),
            b_factors: Vec::with_capacity(capacity),
            occupancy: Vec::with_capacity(capacity),
            charges: None,
            radii: None,
            sigmas: None,
            epsilons: None,
            num_atoms: 0,
            is_hetatm: Vec::with_capacity(capacity),
        }
    }

    /// Add an atom to the structure
    pub fn add_atom(&mut self, atom: AtomRecord) {
        self.coords.push(atom.x);
        self.coords.push(atom.y);
        self.coords.push(atom.z);
        self.atom_names.push(atom.atom_name);
        self.elements.push(atom.element);
        self.serial_numbers.push(atom.serial);
        self.alt_locs.push(atom.alt_loc);
        self.res_names.push(atom.res_name);
        self.res_ids.push(atom.res_seq);
        self.insertion_codes.push(atom.i_code);
        self.chain_ids.push(atom.chain_id);
        self.b_factors.push(atom.temp_factor);
        self.occupancy.push(atom.occupancy);
        self.is_hetatm.push(atom.is_hetatm);

        // Handle optional fields
        if let Some(charge) = atom.charge {
            self.charges
                .get_or_insert_with(|| Vec::with_capacity(self.num_atoms + 1))
                .push(charge);
        }

        if let Some(radius) = atom.radius {
            self.radii
                .get_or_insert_with(|| Vec::with_capacity(self.num_atoms + 1))
                .push(radius);
        }

        self.num_atoms += 1;
    }
}

impl Default for RawAtomData {
    fn default() -> Self {
        Self::new()
    }
}

