    fn test_euclidean_distance() {
        let a = [0.0, 0.0, 0.0];
        let b = [1.0, 0.0, 0.0];
        assert!((euclidean_distance(&a, &b) - 1.0).abs() < 1e-6);

        let c = [1.0, 1.0, 1.0];
        let d = [2.0, 2.0, 2.0];
        let expected = 3.0f32.sqrt();
