    #[test]
    fn test_parse_cif_values_simple() {
        let line =
            "ATOM 1 N N . ALA A 1 1 ? 20.154 29.699 5.276 1.00 49.05 ? ? ? ? ? ? 1 ALA A N 1";
        let values = parse_cif_values(line);
        assert!(values.len() > 10);
        assert_eq!(values[0], "ATOM");
