#[derive(Error, Debug)]
pub enum NewickError {
    #[error("IO error: {0}")]
    Io(#[from] std::io::Error),
    #[error("Invalid format: {0}")]
    InvalidFormat(String),
}

pub struct TreeArrays {
    pub adjacency: Vec<Vec<f32>>, // Dense adjacency for TREX: n_nodes x n_nodes
    pub parents: Vec<i32>,
    pub post_order: Vec<i32>,
    pub leaf_names: Vec<String>,
    pub n_leaves: usize,
}

struct RawNode {
    name: String,
    parent: Option<usize>,
    children: Vec<usize>,
    is_leaf: bool,
}

pub fn parse_newick<P: AsRef<Path>>(path: P) -> Result<TreeArrays, NewickError> {
    let content = fs::read_to_string(path)?;
    let content = content.trim();
    if !content.ends_with(';') {
        return Err(NewickError::InvalidFormat(
            "Newick must end with ';'".into(),
        ));
    }

    let content = &content[..content.len() - 1]; // strip ;

    let mut nodes: Vec<RawNode> = Vec::new();
    let mut stack: Vec<usize> = Vec::new();
    let mut current_name = String::new();

    // Simple state machine for Newick parsing
    let chars: Vec<char> = content.chars().collect();
    let mut i = 0;

    while i < chars.len() {
        match chars[i] {
            '(' => {
                // Start a new internal node
                let node_idx = nodes.len();
                nodes.push(RawNode {
                    name: String::new(),
                    parent: stack.last().cloned(),
                    children: Vec::new(),
                    is_leaf: false,
                });
                if let Some(&p_idx) = stack.last() {
                    nodes[p_idx].children.push(node_idx);
                }
                stack.push(node_idx);
                i += 1;
            }
            ')' | ',' => {
                // If we have a name (leaf name or internal label), finalize it
                if !current_name.is_empty() {
                    let node_idx = nodes.len();
                    nodes.push(RawNode {
                        name: current_name.clone(),
                        parent: stack.last().cloned(),
                        children: Vec::new(),
                        is_leaf: true,
                    });
                    if let Some(&p_idx) = stack.last() {
                        nodes[p_idx].children.push(node_idx);
                    }
                    current_name.clear();
                }

                if chars[i] == ')' {
                    // Close the current internal node
                    stack.pop();
                    // Internal labels can follow ')'
                    i += 1;
                    while i < chars.len() && !matches!(chars[i], '(' | ')' | ',' | ':' | ';') {
                        nodes[*stack.last().unwrap_or(&0)].name.push(chars[i]);
                        i += 1;
                    }
                    continue; // Skip the i+=1 at bottom
                }
                i += 1;
            }
            ':' => {
                // Skip branch lengths for now
                i += 1;
                while i < chars.len() && !matches!(chars[i], '(' | ')' | ',' | ';') {
                    i += 1;
                }
            }
            ' ' | '\n' | '\t' | '\r' => {
                i += 1;
            }
            _ => {
                current_name.push(chars[i]);
                i += 1;
            }
        }
    }

    // Finalize if root was a single leaf (rare)
    if !current_name.is_empty() {
        nodes.push(RawNode {
            name: current_name,
            parent: None,
            children: Vec::new(),
            is_leaf: true,
        });
    }

    // Post-process into JAX-compatible arrays
    // Leaves first, then internal nodes
    let mut leaf_indices = Vec::new();
    let mut internal_indices = Vec::new();
    for (idx, node) in nodes.iter().enumerate() {
        if node.children.is_empty() {
            leaf_indices.push(idx);
        } else {
            internal_indices.push(idx);
        }
    }

    let n_leaves = leaf_indices.len();
    let n_internal = internal_indices.len();
    let n_all = n_leaves + n_internal;

    // Map raw node indices to output indices [leaves..., internal...]
    let mut raw_to_out = vec![0; nodes.len()];
    let mut leaf_names = Vec::new();
    for (i, &raw_idx) in leaf_indices.iter().enumerate() {
        raw_to_out[raw_idx] = i;
        leaf_names.push(nodes[raw_idx].name.clone());
    }
    for (i, &raw_idx) in internal_indices.iter().enumerate() {
        raw_to_out[raw_idx] = n_leaves + i;
    }

    let mut parents = vec![-1; n_all];
    let mut adjacency = vec![vec![0.0; n_all]; n_all];

    for (idx, node) in nodes.iter().enumerate() {
        let out_idx = raw_to_out[idx];
        if let Some(p_raw) = node.parent {
            let p_out = raw_to_out[p_raw];
            parents[out_idx] = p_out as i32;
            adjacency[out_idx][p_out] = 1.0;
        } else {
            // Root
            parents[out_idx] = out_idx as i32;
            adjacency[out_idx][out_idx] = 1.0;
        }
    }

    // Compute post-order
    let mut post_order = Vec::new();
    let mut visited = vec![false; nodes.len()];
    let root_raw = nodes.iter().position(|r| r.parent.is_none()).unwrap_or(0);

    // Simple iterative post-order traversal
    let mut work_stack = vec![(root_raw, false)];
    while let Some((idx, processed)) = work_stack.pop() {
        if processed {
            post_order.push(raw_to_out[idx] as i32);
        } else {
            work_stack.push((idx, true));
            for &child in nodes[idx].children.iter().rev() {
                work_stack.push((child, false));
            }
        }
    }

    Ok(TreeArrays {
        adjacency,
        parents,
        post_order,
        leaf_names,
        n_leaves,
    })
}

#[cfg(test)]
mod tests {
    use crate::formats::newick::parse_newick;
    use std::io::Write;
    use std::fs::{File, remove_file};
    use std::path::{Path, PathBuf};
    use std::sync::atomic::{AtomicU64, Ordering};

    static COUNTER: AtomicU64 = AtomicU64::new(0);

    struct TempFile(PathBuf);

    impl TempFile {
        fn new(content: &str) -> Self {
            let id = COUNTER.fetch_add(1, Ordering::SeqCst);
            let path = PathBuf::from(format!("/tmp/proxide_newick_{}.nwk", id));
            let mut file = File::create(&path).unwrap();
            write!(file, "{}", content).unwrap();
            TempFile(path)
        }
        fn path(&self) -> &Path {
            &self.0
        }
    }

    impl Drop for TempFile {
        fn drop(&mut self) {
            let _ = remove_file(&self.0);
        }
    }

    #[test]
    fn test_parse_basic() {
        let tmp = TempFile::new("(A,B);");
        let tree = parse_newick(tmp.path()).unwrap();
        assert_eq!(tree.n_leaves, 2);
        assert_eq!(tree.leaf_names.len(), 2);
        assert!(tree.leaf_names.contains(&"A".to_string()));
        assert!(tree.leaf_names.contains(&"B".to_string()));
    }

    #[test]
    fn test_parse_branch_lengths() {
        let tmp = TempFile::new("(A:0.1,B:0.2);");
        let tree = parse_newick(tmp.path()).unwrap();
        assert_eq!(tree.n_leaves, 2);
    }

    #[test]
    fn test_parse_nested() {
        let tmp = TempFile::new("((A,B),C);");
        let tree = parse_newick(tmp.path()).unwrap();
        assert_eq!(tree.n_leaves, 3);
    }

    #[test]
    fn test_parse_labels() {
        let tmp = TempFile::new("(A,B)Root;");
        let tree = parse_newick(tmp.path()).unwrap();
        assert_eq!(tree.n_leaves, 2);
    }

    #[test]
    fn test_invalid_format() {
        let tmp = TempFile::new("(A,B)");
        let result = parse_newick(tmp.path());
        assert!(result.is_err());
    }
}

//! PDB file format parser
//!  
//! High-performance parser for Protein Data Bank (PDB) files.
//! Returns raw atom data matching the proxide format.

use proxide_core::structure::{AtomRecord, RawAtomData};
use std::fs::File;
use std::io::{BufRead, BufReader};
use std::path::Path;

/// Parse a PDB ATOM/HETATM line using fixed-width fields
/// Format: https://www.wwpdb.org/documentation/file-format-content/format33/sect9.html
fn parse_atom_line(line: &str) -> Option<AtomRecord> {
    if line.len() < 54 {
        return None;
    }

    let record_type = line[0..6].trim();
    if record_type != "ATOM" && record_type != "HETATM" {
        return None;
    }

    // Helper to parse float from fixed-width field
    let parse_f32 = |s: &str| -> Option<f32> { s.trim().parse().ok() };

    // Helper to parse int from fixed-width field
    let parse_i32 = |s: &str| -> Option<i32> { s.trim().parse().ok() };

    Some(AtomRecord {
        serial: parse_i32(&line[6..11])?,
        atom_name: line[12..16].trim().to_string(),
        alt_loc: line.chars().nth(16).unwrap_or(' '),
        res_name: line[17..20].trim().to_string(),
        chain_id: line[21..22].trim().to_string(),
        res_seq: parse_i32(&line[22..26])?,
        i_code: line.chars().nth(26).unwrap_or(' '),
        x: parse_f32(&line[30..38])?,
        y: parse_f32(&line[38..46])?,
        z: parse_f32(&line[46..54])?,
        occupancy: if line.len() >= 60 {
            parse_f32(&line[54..60]).unwrap_or(1.0)
        } else {
            1.0
        },
        temp_factor: if line.len() >= 66 {
            parse_f32(&line[60..66]).unwrap_or(0.0)
        } else {
            0.0
        },
        element: if line.len() >= 78 {
            line[76..78].trim().to_string()
        } else {
            // Infer from atom name (first character)
            line[12..16]
                .trim()
                .chars()
                .next()
                .map(|c| c.to_string())
                .unwrap_or_default()
        },
        charge: None,
        radius: None,
        is_hetatm: record_type == "HETATM",
    })
}

/// Parse PDB file and return raw atom data with model IDs.
/// Parses all models by default. Use `filter_models()` to select specific models.
pub fn parse_pdb_file<P: AsRef<Path>>(
    path: P,
) -> Result<(RawAtomData, Vec<usize>), Box<dyn std::error::Error>> {
    let file = File::open(path)?;
    let reader = BufReader::new(file);

    let mut raw_data = RawAtomData::new();
    let mut model_ids: Vec<usize> = Vec::new();
    let mut current_model: usize = 1; // Default model 1 if no MODEL record

    for line in reader.lines() {
        let line = line?;
        let trimmed = line.trim();

        if trimmed.starts_with("MODEL") {
            // Parse model number from MODEL record
            if let Some(model_str) = trimmed.get(10..) {
                if let Ok(model_num) = model_str.trim().parse::<usize>() {
                    current_model = model_num;
                }
            }
        } else if trimmed.starts_with("ENDMDL") {
            // Model ends, next atoms belong to next model
            // current_model will be updated by next MODEL record
        } else if trimmed.starts_with("ATOM") || trimmed.starts_with("HETATM") {
            if let Some(atom) = parse_atom_line(&line) {
                raw_data.add_atom(atom);
                model_ids.push(current_model);
            }
        }
    }

    if raw_data.num_atoms == 0 {
        return Err("No atoms found in PDB file".into());
    }

    Ok((raw_data, model_ids))
}

