//! LRU Cache for formatted structure outputs
//!
//! Provides caching of formatted structure data to avoid re-formatting
//! the same structure multiple times.

use std::collections::HashMap;
use std::hash::{Hash, Hasher};
use std::sync::Mutex;

use proxide_core::spec::CoordFormat;

/// Cache key combining file path hash and format specification
#[derive(Debug, Clone, Eq, PartialEq)]
pub struct CacheKey {
    path_hash: u64,
    format: CoordFormat,
    remove_solvent: bool,
    include_hetatm: bool,
}

impl Hash for CacheKey {
    fn hash<H: Hasher>(&self, state: &mut H) {
        self.path_hash.hash(state);
        (self.format as u8).hash(state);
        self.remove_solvent.hash(state);
        self.include_hetatm.hash(state);
    }
}

impl CacheKey {
    pub fn new(
        path: &str,
        format: CoordFormat,
        remove_solvent: bool,
        include_hetatm: bool,
    ) -> Self {
        use std::collections::hash_map::DefaultHasher;
        let mut hasher = DefaultHasher::new();
        path.hash(&mut hasher);
        let path_hash = hasher.finish();

        Self {
            path_hash,
            format,
            remove_solvent,
            include_hetatm,
        }
    }
}

/// Cached formatted structure data
#[derive(Debug, Clone)]
pub struct CachedStructure {
    pub coordinates: Vec<f32>,
    pub atom_mask: Vec<f32>,
    pub aatype: Vec<i8>,
    pub residue_index: Vec<i32>,
    pub chain_index: Vec<i32>,
    pub _num_residues: usize,
    /// Optional atom names (for Full format)
    pub atom_names: Option<Vec<String>>,
    /// Optional coordinate shape (for Full format)
    pub coord_shape: Option<(usize, usize, usize)>,
}

pub struct CachedStructureArgs {
    pub coordinates: Vec<f32>,
    pub atom_mask: Vec<f32>,
    pub aatype: Vec<i8>,
    pub residue_index: Vec<i32>,
    pub chain_index: Vec<i32>,
    pub num_residues: usize,
    pub atom_names: Option<Vec<String>>,
    pub coord_shape: Option<(usize, usize, usize)>,
}

impl CachedStructure {
    pub fn new(args: CachedStructureArgs) -> Self {
        Self {
            coordinates: args.coordinates,
            atom_mask: args.atom_mask,
            aatype: args.aatype,
            residue_index: args.residue_index,
            chain_index: args.chain_index,
            _num_residues: args.num_residues,
            atom_names: args.atom_names,
            coord_shape: args.coord_shape,
        }
    }
}

/// LRU Cache with fixed capacity
pub struct FormatCache {
    cache: HashMap<CacheKey, CachedStructure>,
    order: Vec<CacheKey>,
    capacity: usize,
}

impl FormatCache {
    pub fn new(capacity: usize) -> Self {
        Self {
            cache: HashMap::with_capacity(capacity),
            order: Vec::with_capacity(capacity),
            capacity,
        }
    }

    pub fn get(&mut self, key: &CacheKey) -> Option<&CachedStructure> {
        if self.cache.contains_key(key) {
            // Move to end (most recently used)
            if let Some(pos) = self.order.iter().position(|k| k == key) {
                let k = self.order.remove(pos);
                self.order.push(k);
            }
            self.cache.get(key)
        } else {
            None
        }
    }

    pub fn insert(&mut self, key: CacheKey, value: CachedStructure) {
        if self.cache.len() >= self.capacity && !self.cache.contains_key(&key) {
            // Evict least recently used
            if let Some(lru_key) = self.order.first().cloned() {
                self.cache.remove(&lru_key);
                self.order.remove(0);
            }
        }

        if !self.cache.contains_key(&key) {
            self.order.push(key.clone());
        }
        self.cache.insert(key, value);
    }

    pub fn _len(&self) -> usize {
        self.cache.len()
    }

    pub fn _is_empty(&self) -> bool {
        self.cache.is_empty()
    }

    pub fn _clear(&mut self) {
        self.cache.clear();
        self.order.clear();
    }
}

// Global cache instance (thread-safe)
lazy_static::lazy_static! {
    static ref GLOBAL_CACHE: Mutex<FormatCache> = Mutex::new(FormatCache::new(100));
}

/// Get a structure from the global cache
pub fn get_cached(key: &CacheKey) -> Option<CachedStructure> {
    let mut cache = GLOBAL_CACHE.lock().unwrap();
    cache.get(key).cloned()
}

/// Insert a structure into the global cache
pub fn insert_cached(key: CacheKey, value: CachedStructure) {
    let mut cache = GLOBAL_CACHE.lock().unwrap();
    cache.insert(key, value);
}

/// Clear the global cache
pub fn _clear_cache() {
    let mut cache = GLOBAL_CACHE.lock().unwrap();
    cache._clear();
}

/// Get the current cache size
pub fn _cache_size() -> usize {
    let cache = GLOBAL_CACHE.lock().unwrap();
    cache._len()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_cache_basic() {
        let mut cache = FormatCache::new(2);

        let key1 = CacheKey::new("test1.pdb", CoordFormat::Atom37, true, false);
        let key2 = CacheKey::new("test2.pdb", CoordFormat::Atom37, true, false);
        let key3 = CacheKey::new("test3.pdb", CoordFormat::Atom37, true, false);

        let value = CachedStructure {
            coordinates: vec![1.0, 2.0, 3.0],
            atom_mask: vec![1.0],
            aatype: vec![0],
            residue_index: vec![1],
            chain_index: vec![0],
            _num_residues: 1,
            atom_names: None,
            coord_shape: None,
        };

        cache.insert(key1.clone(), value.clone());
        cache.insert(key2.clone(), value.clone());

        assert_eq!(cache._len(), 2);
        assert!(cache.get(&key1).is_some());
        assert!(cache.get(&key2).is_some());

        // Insert third, should evict LRU
        // Order after inserts: key1, key2
        // After get(key1): key2, key1
        // After get(key2): key1, key2
        // So key1 is LRU and should be evicted when key3 is inserted
        cache.insert(key3.clone(), value);

        assert_eq!(cache._len(), 2);
        // key1 should be evicted (was LRU after accessing key1 then key2)
        assert!(cache.get(&key1).is_none());
        assert!(cache.get(&key2).is_some());
        assert!(cache.get(&key3).is_some());
    }

    #[test]
    fn test_cache_key_different_formats() {
        let key1 = CacheKey::new("test.pdb", CoordFormat::Atom37, true, false);
        let key2 = CacheKey::new("test.pdb", CoordFormat::Atom14, true, false);

        assert_ne!(key1, key2);
    }
}

//! Custom coordinate formatter
//!
//! Allows users to specify exactly which atoms they want extracted per residue.
//! Useful for non-standard representations or specific analysis needs.

#![allow(dead_code)]

use proxide_core::processing::ProcessedStructure;
use proxide_core::spec::OutputSpec;
use std::collections::HashMap;

/// Formatted structure with custom atom selection
#[derive(Debug)]
pub struct FormattedCustom {
    /// Coordinates: (N_res, num_atoms, 3) flattened
    pub coordinates: Vec<f32>,
    /// Atom mask: (N_res, num_atoms) flattened - 1.0 if present, 0.0 if missing
    pub atom_mask: Vec<f32>,
    /// Residue types (0-20)
    pub aatype: Vec<i8>,
    /// Residue indices (PDB numbering)
    pub residue_index: Vec<i32>,
    /// Chain indices
    pub chain_index: Vec<i32>,
    /// The atom names requested (for reference)
    pub requested_atoms: Vec<String>,
    /// Number of atoms per residue in output
    pub atoms_per_residue: usize,
}

/// Custom formatter with user-specified atoms
pub struct CustomFormatter;

impl CustomFormatter {
    /// Format a ProcessedStructure with custom atom selection
    ///
    /// # Arguments
    /// * `processed` - The processed structure to format
    /// * `_spec` - Output specification (unused for direct format call)
    /// * `atom_names` - List of atom names to extract (e.g., ["CA", "CB", "N", "C", "O"])
    pub fn format(
        processed: &ProcessedStructure,
        _spec: &OutputSpec,
        atom_names: &[String],
    ) -> Result<FormattedCustom, String> {
        if atom_names.is_empty() {
            return Err("No atom names specified for custom formatter".to_string());
        }

        let n_res = processed.num_residues;
        let n_atoms = atom_names.len();

        // Build atom name to index mapping
        let atom_to_idx: HashMap<&str, usize> = atom_names
            .iter()
            .enumerate()
            .map(|(i, name)| (name.as_str(), i))
            .collect();

        // Initialize output arrays
        let mut coordinates = vec![f32::NAN; n_res * n_atoms * 3];
        let mut atom_mask = vec![0.0f32; n_res * n_atoms];
        let mut aatype = Vec::with_capacity(n_res);
        let mut residue_index = Vec::with_capacity(n_res);
        let mut chain_index = Vec::with_capacity(n_res);

        // Process each residue
        for (res_idx, res_info) in processed.residue_info.iter().enumerate() {
            aatype.push(res_info.res_type as i8);
            residue_index.push(res_info.res_id);

            // Get chain index
            let c_idx = *processed
                .chain_indices
                .get(&res_info.chain_id)
                .unwrap_or(&0);
            chain_index.push(c_idx as i32);

            // Process atoms in this residue
            for atom_idx in res_info.start_atom..(res_info.start_atom + res_info.num_atoms) {
                let atom_name = &processed.raw_atoms.atom_names[atom_idx];

                if let Some(&slot) = atom_to_idx.get(atom_name.as_str()) {
                    // Calculate output index
                    let out_idx = (res_idx * n_atoms + slot) * 3;

                    // Copy coordinates
                    coordinates[out_idx] = processed.raw_atoms.coords[atom_idx * 3];
                    coordinates[out_idx + 1] = processed.raw_atoms.coords[atom_idx * 3 + 1];
                    coordinates[out_idx + 2] = processed.raw_atoms.coords[atom_idx * 3 + 2];

                    // Set mask
                    atom_mask[res_idx * n_atoms + slot] = 1.0;
                }
            }
        }

        Ok(FormattedCustom {
            coordinates,
            atom_mask,
            aatype,
            residue_index,
            chain_index,
            requested_atoms: atom_names.to_vec(),
            atoms_per_residue: n_atoms,
        })
    }
}

impl FormattedCustom {}

