/// Get water model parameters by name.
///
/// Supported models: TIP3P, SPCE (SPC/E), TIP4PEW (TIP4P-Ew)
///
/// If `rigid` is true, bond and angle force constants are set to 0.0,
/// matching OpenMM's rigidWater=True behavior.
pub fn get_water_model(name: &str, rigid: bool) -> Result<WaterModel, String> {
    let upper = name.to_uppercase();
    let mut model = match upper.as_str() {
        "TIP3P" => tip3p(),
        "SPCE" | "SPC/E" => spce(),
        "TIP4PEW" | "TIP4P-EW" => tip4pew(),
        "HOH" | "WAT" | "SOL" => tip3p(), // Default fallback
        _ => return Err(format!("Unknown water model: {}", name)),
    };

    if rigid {
        // Zero out force constants, keep equilibrium values for constraints
        model.bonds = model
            .bonds
            .into_iter()
            .map(|(a1, a2, length, _)| (a1, a2, length, 0.0))
            .collect();
        model.angles = model
            .angles
            .into_iter()
            .map(|(a1, a2, a3, theta, _)| (a1, a2, a3, theta, 0.0))
            .collect();
    }

    Ok(model)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_tip3p() {
        let model = get_water_model("TIP3P", false).unwrap();
        assert_eq!(model.name, "TIP3P");
        assert_eq!(model.atoms.len(), 3);
        assert!((model.charges["O"] - (-0.834)).abs() < 0.001);
        assert!(!model.has_virtual_sites);
    }

    #[test]
    fn test_tip4pew() {
        let model = get_water_model("TIP4PEW", false).unwrap();
        assert_eq!(model.atoms.len(), 4);
        assert!(model.has_virtual_sites);
        assert!((model.charges["M"] - (-1.04844)).abs() < 0.001);
    }

    #[test]
    fn test_rigid_water() {
        let model = get_water_model("TIP3P", true).unwrap();
        // Force constants should be 0
        for (_, _, _, k) in &model.bonds {
            assert_eq!(*k, 0.0);
        }
        for (_, _, _, _, k) in &model.angles {
            assert_eq!(*k, 0.0);
        }
        // But equilibrium values preserved
        assert!((model.bonds[0].2 - 0.9572).abs() < 0.001);
    }
}

/// Energy conversion: kcal/mol → kJ/mol
pub const KCAL_TO_KJ: f32 = 4.184;

/// Energy conversion: kJ/mol → kcal/mol
pub const KJ_TO_KCAL: f32 = 1.0 / 4.184;

/// Length conversion: nanometers → angstroms
pub const NM_TO_ANGSTROM: f32 = 10.0;

/// Length conversion: angstroms → nanometers
pub const ANGSTROM_TO_NM: f32 = 0.1;

/// Bond force constant conversion factor: kJ/mol/nm² → kcal/mol/Å²
/// Combines energy (kJ/mol → kcal/mol) and length (nm² → Å²) conversions.
pub const BOND_K_FACTOR: f32 = KJ_TO_KCAL / (NM_TO_ANGSTROM * NM_TO_ANGSTROM);

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_energy_roundtrip() {
        let val = 2.5;
        let roundtrip = (val * KCAL_TO_KJ * KJ_TO_KCAL - val).abs();
        assert!(roundtrip < 1e-5, "Energy roundtrip should be precise; got {}", roundtrip);
    }

    #[test]
    fn test_bond_k_factor_sanity() {
        // Expected value: KJ_TO_KCAL / 100.0 ≈ 0.002390057
        let expected = KJ_TO_KCAL / 100.0;
        let diff = (BOND_K_FACTOR - expected).abs();
        assert!(diff < 1e-8, "BOND_K_FACTOR should be ~0.002390057; got {}", BOND_K_FACTOR);
    }
}

//! Unit conversion constants and specifications for proxide parameterizer output.
//!
//! This crate provides conversion factors and unit system specifications for translating
//! from GROMACS-internal units (nm, kJ/mol) to various target unit systems (e.g., AMBER).
//!
//! **Scope**: Applies only to the parameterizer output dict emitted by py_parsers.rs.
//! The proxide-physics internals (kcal/mol + Å) are a separate domain.

pub mod constants;
pub mod registry;

pub use constants::{
    KCAL_TO_KJ, KJ_TO_KCAL, NM_TO_ANGSTROM, ANGSTROM_TO_NM, BOND_K_FACTOR,
};
pub use registry::{UnitSystem, UnitConversionSpec};

use crate::constants::{KJ_TO_KCAL, NM_TO_ANGSTROM, BOND_K_FACTOR};

/// Conversion factors from GROMACS-internal units (nm, kJ/mol) to a target unit system.
///
/// Scope: applies only to the parameterizer output dict emitted by py_parsers.rs.
/// proxide-physics internals (kcal/mol + Å) are a separate domain and out of scope.
///
/// # Future
/// A full graph-based registry (BFS transitive derivation) is planned for custom unit systems.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct UnitConversionSpec {
    /// Factor: nm → target length unit
    pub length: f32,
    /// Factor: kJ/mol → target energy unit
    pub energy: f32,
    /// Factor: kJ/mol/nm² → target bond force constant unit
    pub bond_k: f32,
    /// Factor: kJ/mol/rad² → target angle force constant unit
    pub angle_k: f32,
}

impl UnitConversionSpec {
    /// Create conversion spec for AMBER units (Å + kcal/mol).
    pub fn amber() -> Self {
        Self {
            length: NM_TO_ANGSTROM,
            energy: KJ_TO_KCAL,
            bond_k: BOND_K_FACTOR,
            angle_k: KJ_TO_KCAL,
        }
    }

    /// Create conversion spec for GROMACS units (nm + kJ/mol).
    /// This is the identity conversion (no-op).
    pub fn gromacs() -> Self {
        Self { length: 1.0, energy: 1.0, bond_k: 1.0, angle_k: 1.0 }
    }

    /// Create conversion spec for OpenMM units (nm + kJ/mol).
    /// OpenMM uses nm/kJ internally — same as GROMACS for parameterizer output.
    pub fn openmm() -> Self {
        Self::gromacs()
    }
}

/// Unit system for parameterizer output.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum UnitSystem {
    /// Angstroms + kcal/mol (default, AMBER convention)
    #[default]
    Amber,
    /// Nanometers + kJ/mol (GROMACS convention)
    Gromacs,
    /// Nanometers + kJ/mol (OpenMM internal convention)
    OpenMM,
}

impl UnitSystem {
    /// Get the conversion spec for this unit system.
    pub fn conversion_spec(&self) -> UnitConversionSpec {
        match self {
            Self::Amber => UnitConversionSpec::amber(),
            Self::Gromacs => UnitConversionSpec::gromacs(),
            Self::OpenMM => UnitConversionSpec::openmm(),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_gromacs_identity() {
        let spec = UnitConversionSpec::gromacs();
        assert_eq!(spec.length, 1.0);
        assert_eq!(spec.energy, 1.0);
        assert_eq!(spec.bond_k, 1.0);
        assert_eq!(spec.angle_k, 1.0);
    }

    #[test]
    fn test_amber_length() {
        let spec = UnitConversionSpec::amber();
        assert_eq!(spec.length, 10.0);
    }

    #[test]
    fn test_amber_energy() {
        let spec = UnitConversionSpec::amber();
        let expected = KJ_TO_KCAL;
        let diff = (spec.energy - expected).abs();
        assert!(diff < 1e-8, "AMBER energy should be KJ_TO_KCAL; got {}", spec.energy);
    }

    #[test]
    fn test_unit_system_amber_conversion_spec() {
        let spec = UnitSystem::Amber.conversion_spec();
        assert_eq!(spec.length, 10.0);
    }

    #[test]
    fn test_unit_system_gromacs_conversion_spec() {
        let spec = UnitSystem::Gromacs.conversion_spec();
        assert_eq!(spec.length, 1.0);
    }

    #[test]
