        chain_id: "A".to_string(),
        res_seq: 1,
        i_code: ' ',
        x: 0.0,
        y: 0.0,
        z: 0.0,
        occupancy: 1.0,
        temp_factor: 20.0,
        element: "C".to_string(),
        charge: None,
        radius: None,
        is_hetatm: false,
    });

    let mut structure = ProcessedStructure::from_raw(raw_atoms).unwrap();

    let mut bonds = Vec::new();

    let result = add_hydrogens(&mut structure, &mut bonds);
    assert!(result.is_ok());
